local _, ns = ...
local E = ns.DB.entries
E["npc:mux-manascrambler"] = {t="npc",n="Mux Manascrambler",z="tanaris",s="Mux Manascrambler is an eccentric goblin engineer dwelling in the desert outpost of Gadgetzan. Unlike many of his peers focused strictly on explosives or mining equipment, Mux harbors a peculiar fascination with the supernatural and occult energies.",h="Mux Manascrambler is an eccentric goblin engineer dwelling in the desert outpost of Gadgetzan.",sec={{t="A Tinkerer of the Unseen",b="Tucked away inside a building in central Gadgetzan, behind Driz Plunkbow and his clanking Butcherbots, sits Mux Manascrambler. While the Steamwheedle Cartel trades heavily in oil, guns, and salvage, Mux focuses his ingenuity on more esoteric pursuits: the realm of spirits and supernatural anomalies. He uses his technical acumen to design bizarre devices capable of detecting, distilling, and interacting with spectral remnants, bridging crude goblin craftsmanship with the invisible worlds of the dead.",sp=0}},faq={{q="Where can I find Mux Manascrambler?",a="Mux makes his home in Gadgetzan in northern Tanaris. You can find him tucked inside a building near the center of the desert trading hub, positioned just behind Driz Plunkbow and the meat-carving Butcherbots.",al={"mux location","where is mux","mux manascrambler map"}},{q="What kind of work does Mux do?",a="Mux is an engineer obsessed with spectral and unseen forces. Rather than standard demolitions or transport, he builds specialized contraptions capable of revealing spirits, distilling ectoplasm, and harnessing arcane supernatural power.",al={"mux job","what does mux sell","mux research"}},{q="Does Mux belong to a faction?",a="Mux belongs to the Steamwheedle Cartel operating out of Gadgetzan. As an independent goblin operative, he maintains strict commercial neutrality and is willing to aid adventurers of either the Horde or the Alliance.",al={"is mux horde","is mux neutral","mux alliance"}}},ang={["profession:Engineering"]="Mux is an oddity among goblin tinkers, applying mechanical gears and power cells to capture and distill invisible supernatural forces rather than merely blowing things apart."},kw={"ectoplasm","gadgetzan","ghost","goblin engineer","manascrambler","mux","tanaris"},rel={"subzone:gadgetzan","zone:tanaris","topic:goblin"},src={"Mux Manascrambler"}}
E["npc:narain-soothfancy"] = {t="npc",n="Narain Soothfancy",z="tanaris",s="Narain Soothfancy is an eccentric gnome dwelling in a secluded beach hut just north of Steamwheedle Port in Tanaris. While he loudly advertises himself as a master soothsayer capable of divining the future, those who know him consider his psychic talents a complete farce compared to his genuine engineering genius.",h="Narain Soothfancy is an eccentric gnome dwelling in a secluded beach hut just north of Steamwheedle Port in...",sec={{t="Psychic Visions and Practical Gearing",b="Perched on the eastern coast of Tanaris just north of the goblin docks, Narain Soothfancy lives as a retired engineer turned self-proclaimed master fortune teller. He routinely greets visitors by pressing unopened envelopes against his forehead or making wildly inaccurate guesses about their business, such as wondering if they have arrived seeking the legendary Ashbringer. Despite his theatrical charade, Narain possesses deep technical knowledge. Even ancient beings like the blue dragon Azuregos note that while Narain is a terrible psychic, his engineering aptitude is undeniably brilliant. Travelers often find him useful for resetting specialized trade knowledge using his handbook, 'Soothsaying for Dummies.'",sp=0},{t="A Shoreline Crash",b="Before settling by Steamwheedle Port, Narain suffered a catastrophic flying machine crash far to the south along Land's End Beach. He survived the wreck thanks to an unexpected rescue, though his eccentric personality and strange obsessions have kept him isolated on the desert shores, tinkering with arcane-adjacent technology and peddling dubious prophecies to anyone who passes by.",sp=0}},faq={{q="Who is Narain Soothfancy?",a="Narain Soothfancy is a retired gnome engineer residing in Tanaris north of Steamwheedle Port. He advertises himself as a master soothsayer, though his divinations are famously inaccurate.",al={"narain soothfancy lore","who is narain","tanaris psychic gnome"}},{q="Is Narain actually a psychic?",a="No. Powerful acquaintances like the dragon Azuregos openly describe him as an awful psychic. His true talent lies in masterwork engineering and tinkering, regardless of his theatrical attempts at mind-reading.",al={"can narain see the future","is narain psychic","soothfancy fortune teller"}},{q="What is the book 'Soothsaying for Dummies' beside him?",a="It is a practical manual kept by Narain that allows adventurers to unlearn and relearn specialized trade knowledge, bypassing his absurd psychic theatrics.",al={"soothsaying for dummies","narain tradeskill book"}},{q="How does Narain know Azuregos?",a="Narain is an old associate of the blue dragon Azuregos, who wanders Azshara. Despite Narain's bizarre pretensions, the dragon respects his unmatched engineering and crafting capabilities.",al={"narain and azuregos","blue dragon narain"}}},ang={["profession:Engineering"]="Engineers will find Narain's wild inventions fascinating, even if he prefers to pretend his mechanical triumphs are actually mystical visions.",["race:Gnome"]="Narain exemplifies the eccentric extreme of gnomish ingenuity, pairing brilliant technological problem-solving with bizarre, obsessive hobbies."},kw={"azuregos","engineer","narain","soothfancy","soothsayer","steamwheedle port","tanaris"},rel={"zone:tanaris","subzone:steamwheedle-port","subzone:land-s-end-beach","npc:azuregos","topic:gnome"},src={"Narain Soothfancy"}}
E["npc:senior-surveyor-fizzledowser"] = {t="npc",n="Senior Surveyor Fizzledowser",z="tanaris",s="Senior Surveyor Fizzledowser is an ambitious field researcher stationed in Gadgetzan on behalf of the Gadgetzan Water Company. Tasked with prospecting new water sources amidst heavy Wastewander interference, his surveys accidentally unearth the growing menace of the subterranean silithid.",h="Senior Surveyor Fizzledowser is an ambitious field researcher stationed in Gadgetzan on behalf of the...",sec={{t="A Search for Water Gone Wrong",b="Operating out of Gadgetzan, Senior Surveyor Fizzledowser is primarily occupied with solving the desert town's chronic resource problem. With local wells and water holes constantly seized by hostile Wastewander bandits, the Gadgetzan Water Company must search further afield for untapped reservoirs. To this end, Fizzledowser dispatches scouts armed with dowsing widgets across the dunes, such as toward Sandsorrow Watch. However, instead of finding clean springs, his probes consistently tap into subterranean insect hives, trading one logistical crisis for an impending ecological disaster.",sp=0},{t="Uncovering the Silithid",b="When his surveyor crews began suffering devastating ambushes from armored, burrowing insects, Fizzledowser partnered with Alchemist Pestlezugg to examine the specimens. Further tragedies—including the loss of Junior Surveyor Scrimshank inside the Gaping Chasm—proved that these were not ordinary desert pests, but coordinated vanguard forces known as the silithid. Alarmed by findings pointing toward a threat capable of overwhelming southern Kalimdor, Fizzledowser looks past goblin neutrality to sound the alarm directly to Horde and Alliance leadership.",sp=1}},faq={{q="Who is Senior Surveyor Fizzledowser?",a="He is an engineer and field supervisor for the Gadgetzan Water Company. His duty is to scout viable water wells across the desert of Tanaris to keep Gadgetzan supplied.",al={"who is fizzledowser","fizzledowser tanaris","gadgetzan surveyor"}},{q="What is the Gadgetzan Water Company?",a="It is a commercial enterprise operating out of Gadgetzan responsible for securing, processing, and distributing water in the arid desert of Tanaris, where moisture is the most valuable commodity.",al={"gadgetzan water company","who does fizzledowser work for"}},{q="What happened to Junior Surveyor Scrimshank?",a="Junior Surveyor Scrimshank was sent to prospect near the Gaping Chasm but disappeared after the area was overrun by silithid. Adventurers sent to find him discover only his abandoned gear deep within the bug nests.",al={"where is scrimshank","scrimshank redemption","what happened to scrimshank"},sp=1},{q="Why is Fizzledowser concerned about the desert insects?",a="What initially seemed like native predators turned out to be organized swarms of silithid expanding aggressively from underground. Alchemical analysis confirmed their coordination poses an existential danger to all settlements in southern Kalimdor.",al={"why investigate bugs","noxious lair investigation","silithid threat tanaris"}}},ang={["profession:Engineering"]="Fizzledowser relies on custom goblin-engineered dowsing widgets to pinpoint hidden water sources beneath the shifting sands."},kw={"dowsing widget","fizzledowser","gadgetzan","gaping chasm","pestlezugg","scrimshank","silithid","tanaris","water company"},rel={"subzone:gadgetzan","zone:tanaris","subzone:sandsorrow-watch","subzone:gaping-chasm","subzone:noxious-lair","topic:goblin","topic:alliance","topic:horde"},src={"Senior Surveyor Fizzledowser"}}
E["npc:yeh-kinya"] = {t="npc",n="Yeh'kinya",z="tanaris",s="Yeh'kinya is a jungle troll scholar residing at Steamwheedle Port on the desert coast of Tanaris. Claiming to seek ancient lore and artifacts to understand dark powers, he dispatches willing adventurers across Azeroth on missions to gather lost troll relics.",h="Yeh'kinya is a jungle troll scholar residing at Steamwheedle Port on the desert coast of Tanaris.",sec={{t="The Scholar at Steamwheedle Port",b="Lounging among the goblins and dockworkers of Steamwheedle Port, Yeh'kinya presents himself as a quiet student of history and spirits. He recruits travelers to track down obscure magical items across Kalimdor and the Eastern Kingdoms, from ancient eggs in the Hinterlands to stone prophecy tablets buried in the ruins of Zul'Farrak. While he claims these errands serve peaceful academic inquiry into ancient troll history, his specific focus on the blood god Hakkar draws suspicion from watchful onlookers.",sp=0},{t="The Serpent's Deceit",b="Beneath his scholarly guise, Yeh'kinya is a fanatical worshipper of Hakkar the Soulflayer. Every artifact and soul essence he gathers is carefully manipulated to prepare for the dread Blood God's physical rebirth into Azeroth. Once his plot is pieced together and exposed by Prospector Ironboot, Yeh'kinya sheds all pretense of friendship. Rather than answering for his treason, he transforms into a green wind serpent and flees across the open sea toward the south seas, leaving duped heroes to seek aid from the Zandalari on Yojamba Isle.",sp=2}},faq={{q="Who is Yeh'kinya?",a="Yeh'kinya is a jungle troll found standing near the water at Steamwheedle Port in Tanaris. Outwardly, he acts as a scholar seeking historical relics and spirits, but he is secretly a covert agent working to orchestrate the return of Hakkar the Soulflayer.",al={"yeh'kinya lore","who is yehkinya","yehkinya npc"},sp=2},{q="Why does Yeh'kinya want the Prophecy of Mosh'aru and the Ancient Egg?",a="Yeh'kinya tricks adventurers into recovering these powerful artifacts under the guise of safe research. In truth, the Mosh'aru tablets contain rituals and lore concerning the binding and summoning of Hakkar, and the items provided help pave the way for the Soulflayer's physical manifestation in Zul'Gurub.",al={"why ancient egg","prophecy of mosharu troll","yehkinya purpose"},sp=2},{q="How is Yeh'kinya exposed?",a="Prospector Ironboot uncovers the truth behind the scholar's requests and alerts the adventurer. When confronted with evidence of his deception, Yeh'kinya abandons his guise, transforms into a flying green wind serpent, and escapes over the ocean to join his cultist allies.",al={"who finds out yehkinya","confront yehkinya","prospector ironboot yehkinya"},sp=1},{q="What should adventurers do after Yeh'kinya escapes?",a="Following Yeh'kinya's flight, Prospector Ironboot directs duped heroes to Yojamba Isle off the coast of Stranglethorn Vale. There, the Zandalari tribe has gathered to rally champions and find a way to halt Hakkar's return.",al={"where to go after yehkinya","next step after confront yehkinya","yehkinya escape"},sp=1}},ang={["race:Troll"]="Darkspear trolls recognize the mortal peril of Hakkar's resurgence; being tricked into aiding a Hakkari cultist is a bitter sting against the tribe's defiance of the Blood God.",["class:Priest"]="Priests sensitive to spiritual essence may find Yeh'kinya's casual collection of trapped screecher spirits deeply troubling long before his true loyalty to Hakkar is unmasked."},kw={"hakkar","ironboot","mosh'aru","soulflayer","steamwheedle port","tanaris","wind serpent","yeh'kinya","yehkinya"},rel={"subzone:steamwheedle-port","zone:tanaris","subzone:yojamba-isle","subzone:zul-gurub","topic:troll"},src={"Yeh'kinya"}}
E["subzone:bootlegger-outpost"] = {t="subzone",n="Bootlegger Outpost",z="tanaris",s="Bootlegger Outpost is a precarious Steamwheedle Cartel encampment perched on the lip of the Gaping Chasm in southern Tanaris. Dispatched under orders from Marin Noggenfogger, the resident goblins are tasked with turning the menacing silithid infestation into a profitable venture or exterminating them entirely.",h="Bootlegger Outpost is a precarious Steamwheedle Cartel encampment perched on the lip of the Gaping Chasm in...",sec={{t="On the Brink of the Swarm",b="Perched directly over the insect-carved ravines of the Gaping Chasm, Bootlegger Outpost serves as Gadgetzan's frontline stake against the creeping silithid swarms. Established by the venture-seeking alchemist Marin Noggenfogger, the outpost's purpose is simple and ruthlessly practical: figure out how to turn the encroaching insectoid threat into cold, hard coin, or eradicate them if they prove unprofitable. Its inhabitants balance scientific observation with armed vigilance, surviving on the razor's edge between lucrative research and total swarm annihilation.",sp=0},{t="A Base for Eccentrics",b="Beyond routine silithid surveillance, the windswept tents draw oddities from across the Steamwheedle trade routes. Eccentric figures such as the fortune-teller Narain Soothfancy set up shop along the canyon ledge, hauling along unusual arcane paraphernalia like his instructional guide, Soothsaying for Dummies. Isolated from the hustle of Gadgetzan proper, the outpost remains a haven for risky schemes, experimental studies, and desperate gambles in the sands.",sp=0}},faq={{q="What is Bootlegger Outpost?",a="Bootlegger Outpost is a small Steamwheedle Cartel encampment stationed on the southern rim of the Gaping Chasm in Tanaris, built to monitor and exploit the local silithid population.",al={"bootlegger outpost purpose","what is this place","who built bootlegger outpost"}},{q="Why did the goblins build a base right next to the silithid hives?",a="Marin Noggenfogger dispatched the goblins here on a dual mandate: find a profitable angle on the invasive silithid hives or wipe the insects completely off the desert map.",al={"why are goblins here","who sent the goblins","marin noggenfogger mission"}},{q="Who is Narain Soothfancy?",a="Narain Soothfancy is an eccentric gnome soothsayer who resides at the outpost, famous for divining fortunes and writing the instructional tome Soothsaying for Dummies.",al={"narain soothfancy","soothsaying for dummies","fortune teller tanaris"}},{q="Which cartel faction controls the camp?",a="The outpost is run by the Steamwheedle Cartel. While closely tied to nearby Gadgetzan, its operations and trade ties connect back to broader Steamwheedle ports across Kalimdor.",al={"is this gadgetzan","who owns bootlegger outpost","cartel alignment"}}},ang={["profession:Engineering"]="Living within striking range of massive insect hives requires inventive defenses, making the outpost an appealing stop for tinkers curious about makeshift desert survival tech."},kw={"bootlegger","gaping chasm","narain","noggenfogger","outpost","silithid","soothfancy","steamwheedle","tanaris"},rel={"zone:tanaris","subzone:gaping-chasm","subzone:gadgetzan","npc:narain-soothfancy","topic:steamwheedle-cartel","topic:goblin","subzone:ratchet"},src={"Bootlegger Outpost"}}
E["subzone:broken-pillar"] = {t="subzone",n="Broken Pillar",z="tanaris",s="The Broken Pillar is a weathered cluster of ancient troll ruins jutting from the dunes south of Gadgetzan. It serves as an isolated research post for the goblin prospector and scientist Marvon Rivetseeker, who studies the enigmatic artifacts buried beneath the surrounding sands.",h="The Broken Pillar is a weathered cluster of ancient troll ruins jutting from the dunes south of Gadgetzan.",sec={{t="Sun-Bleached Stone",b="Rising out of the sands south of Gadgetzan and east of the treacherous Abyssal Sands, the Broken Pillar marks the remnants of ancient troll architecture long swallowed by Tanaris. Despite the desolate surroundings and encroaching desert beasts, the site offers rare clues to the continent's prehistoric civilisations. Marvon Rivetseeker, a goblin researcher originally based out of Ratchet, has established a lonely camp beside the shattered stonework to examine curious relics known as Gahz'ridian scattered across the waste.",sp=0}},faq={{q="What is the Broken Pillar?",a="The Broken Pillar is an ancient troll ruin located in central Tanaris, south of Gadgetzan and east of the Abyssal Sands. Little remains of the original structure aside from weathered stone pillars and debris half-buried in the shifting dunes.",al={"broken pillar tanaris","what is broken pillar","pillar ruins"}},{q="Who is camped at the Broken Pillar?",a="Marvon Rivetseeker, an inquisitive goblin scientist and prospector from Ratchet, has set up a solitary research camp among the ruins. He investigates the mysterious Gahz'ridian ornaments buried throughout the surrounding desert.",al={"who is at broken pillar","broken pillar npc","marvon rivetseeker location"}},{q="Who built the original ruins here?",a="The stonework is of ancient troll design, dating back to the eras when ancient troll empires held dominion across southern Kalimdor long before desert sands engulfed the region.",al={"who built broken pillar","broken pillar history","broken pillar origin"}},{q="What are Gahz'ridian relics?",a="Gahz'ridian are ancient stone artifacts and carved faces buried in the sands of Tanaris. Marvon Rivetseeker studies them from his camp at the Broken Pillar to unlock the secrets and power held within the vanished empire's craft.",al={"gahzridian","what is gahzridian","marvon quest items"}}},ang={["race:Troll"]="The crumbling pillars are solemn markers of ancestral troll architecture, echoing an era before the empire's dominion over southern Kalimdor was fractured by time and sand.",["race:Gnome"]="The curiosity driving Marvon Rivetseeker's research into unknown relic properties mirrors gnomish scholarly ambition, though his methods remain distinctively goblin."},kw={"broken pillar","gadgetzan","gahz'ridian","marvon rivetseeker","ratchet","tanaris","troll ruins"},rel={"zone:tanaris","subzone:gadgetzan","subzone:ratchet","topic:troll","topic:goblin"},src={"Broken Pillar"}}
E["subzone:caverns-of-time"] = {t="subzone",n="Caverns of Time",z="tanaris",s="Tucked into the eastern cliffs of Tanaris, the Caverns of Time serve as the mystical lair of Nozdormu and the bronze dragonflight. Within its winding depths, the dragons monitor and safeguard the fragile timeways of Azeroth against any mortal intrusion or temporal tampering.",h="Tucked into the eastern cliffs of Tanaris, the Caverns of Time serve as the mystical lair of Nozdormu and the...",sec={{t="The Winding Timeways",b="Carved deep beneath the desert cliffs, the Caverns of Time are a nexus where the currents of history converge. Charged by the titans at the dawn of the world, Nozdormu the Timeless One and his bronze dragonflight act as eternal sentinels over these corridors. Inside, time behaves erratically; glimpses of past and future slip through hidden rifts, and relics plucked from distant eras lie scattered across the sands. While the great wyrm Anachronos keeps watch near the entrance, lesser bronze drakes patrol the winding descent, fiercely protective of the one true timeline.",sp=0},{t="A Hoard of Eras",b="Beyond being a junction of past and future, the caverns serve as an eccentric vault. Over millennia, the bronze flight has gathered historical fragments from every corner of Azeroth: ancient dwarven structures, a watchtower from Lordaeron, chieftain quarters from the orcish clans, and armor dating back to the first kings of Stromgarde. Yet despite the occasional traveler daring to slip past the sentinels to glimpse these wonders, the inner gateways remain tightly shut, awaiting the day the flight deems mortal intervention necessary.",sp=0}},faq={{q="Can I go inside the Caverns of Time right now?",a="You can walk down the long winding tunnel into the main chamber, but the historical portals themselves remain sealed. You must be careful around the drakes patrolling the entrance; while the elder bronze dragon Anachronos remains indifferent to travelers, his companions will attack any mortal who strays too close.",al={"can i enter caverns of time","how to enter caverns of time","is caverns of time open"}},{q="Who rules over the Caverns of Time?",a="The caverns belong to Nozdormu the Timeless One, the Dragon Aspect empowered by the titans to oversee time. Day-to-day stewardship and guarding of the entrance often fall to his prime scion, Anachronos, alongside the guardians of the bronze dragonflight.",al={"who leads caverns of time","caverns of time boss","who lives in caverns of time"}},{q="Why are there random buildings and artifacts inside?",a="Nozdormu spent ages cataloging and collecting physical relics from across Azeroth's history. Scattered across the caverns are misplaced treasures, including an entire Lordaeron guard tower, dwarven architecture, orcish structures, and weapons from long-forgotten mortal kingdoms.",al={"why are there human towers in caverns of time","artifacts in caverns of time"}},{q="What is the purpose of the bronze dragonflight here?",a="Their sacred duty, granted by the titans, is to safeguard the flow of time and maintain the integrity of history. They ensure that mortal tampering or outside disruptions do not unravel the events that define the world.",al={"what do bronze dragons do here","bronze flight purpose"}}},ang={["class:Mage"]="The temporal magic saturating the caverns far exceeds mortal chronomancy, offering a humbling glimpse at forces beyond arcane manipulation.",["race:NightElf"]="The kaldorei remember the ancient pacts of the Dragon Aspects well, regarding Nozdormu's charge as essential to preserving the world's survival."},kw={"anachronos","bronze dragonflight","caverns of time","nozdormu","tanaris","temporal","timeways"},rel={"zone:tanaris","topic:titan","topic:lordaeron","topic:second-war","subzone:stratholme"},src={"Caverns of Time"}}
E["subzone:circle-of-aquementas"] = {t="subzone",n="Circle of Aquementas",z="tanaris",s="The Circle of Aquementas is a mysterious ring of upright standing stones positioned along the eastern shoreline of Tanaris, just south of Lost Rigger Cove. It serves as a ritual site where travelers can call forth the elemental spirit Aquementas.",h="The Circle of Aquementas is a mysterious ring of upright standing stones positioned along the eastern...",sec={{t="A Ring by the Sea",b="Tucked away along the windswept eastern coast of Tanaris, the Circle of Aquementas sits quietly south of the pirate stronghold at Lost Rigger Cove. Composed of weathered, upright stones arranged in a circular formation, this unusual site hums with elemental energy against the desert shore. It acts as a focus for summoning Aquementas, an elemental entity tied to an ancient artifact. While the surrounding beaches crawl with Southsea brigands and roaming sea creatures, the circle itself remains a solemn pocket of ritual power amidst the dunes.",sp=0}},faq={{q="What is the Circle of Aquementas?",a="It is a circular arrangement of upright standing stones situated on the southeastern coastline of Tanaris, used to summon the elemental entity Aquementas.",al={"what is this stone ring","circle of aquementas purpose","standing stones tanaris"}},{q="Where is the circle located?",a="The circle lies on the eastern shore of Tanaris, directly south of the cliffs and entrance leading to Lost Rigger Cove.",al={"where is circle of aquementas","how to find circle of aquementas","circle of aquementas location"}},{q="Who is Aquementas?",a="Aquementas is an elemental spirit linked to an ancient quest line involving strange artifacts, summoned directly into the circle of stones.",al={"who is aquementas","aquementas lore"}},{q="Is the circle guarded by pirates?",a="While Southsea pirates prowl nearby Lost Rigger Cove and the surrounding shoreline, the circle itself is primarily an isolated site for summoning.",al={"are there pirates here","southsea pirates near circle"}}},ang={["class:Shaman"]="The circle's ability to focus primal energies and anchor an elemental spirit makes it an intriguing curiosity for any shaman wandering the Tanaris coast."},kw={"aquementas","circle of aquementas","elemental","lost rigger cove","standing stones","tanaris"},rel={"zone:tanaris","subzone:lost-rigger-cove","topic:pirate"},src={"Circle of Aquementas"}}
E["subzone:deserted-workshop"] = {t="subzone",n="Deserted Workshop",z="tanaris",s="Tucked against the dunes northwest of Gadgetzan, the Deserted Workshop is an enigmatic crash site nestled along the border mountains. Marked by skid tracks descending from Thousand Needles and a wrecked rocket car embedded in the hillside, it stands as a silent testament to a high-speed technological disaster.",h="Tucked against the dunes northwest of Gadgetzan, the Deserted Workshop is an enigmatic crash site nestled...",sec={{t="A High-Velocity Blunder",b="Just northwest of the bustling goblin trading post of Gadgetzan lies a lonely hillside littered with scorched metal and scrap. At the center of the wreckage rests a shattered rocket car, its frame crushed against the rocky incline. Deep skid tracks trace its erratic journey from high in the northern mountains dividing Tanaris and Thousand Needles. While the site sits abandoned and offers no obvious clues to the driver's fate, its design is unmistakable to anyone familiar with the intense vehicle trials across the ridge.",sp=0},{t="Echoes of the Salt Flats",b="The crashed racer matches the high-strung, volatile drag carts built and tested on the Mirage Raceway down in the Shimmering Flats. It seems an intrepid—or reckless—engineer managed to launch their contraption straight through the mountain pass, ending a disastrous test run in the sands of Tanaris. With no survivor in sight, the desert winds slowly bury the wreckage beside the dusty ridges.",sp=0}},faq={{q="What is the wrecked vehicle embedded in the hill?",a="It is a wrecked rocket car, identical to the volatile racing vehicles engineered for high-speed trials on the nearby salt flats. Judging by the skid marks leading down from the ridge, a driver lost control high in the mountains and crashed hard into the Tanaris hillside.",al={"what crashed here","wrecked car","crashed rocket","broken cart tanaris"}},{q="Where did the crashed car come from?",a="The tread marks and gouges in the rock trace northward into the steep mountains bordering Thousand Needles. It almost certainly originated from the Mirage Raceway in the Shimmering Flats, where gnomes and goblins constantly test reckless rocket-propulsion prototypes.",al={"where did it come from","where do the tracks lead","crash tracks"}},{q="Who was driving the rocket car?",a="The driver's identity remains unknown, and no body or survivor lingers at the crash site. Whether they were recovered, managed to limp away back to Gadgetzan, or perished to the local scavengers is left entirely to mystery.",al={"who crashed","driver body","who was in the cart"}},{q="Why is the area called the Deserted Workshop?",a="Despite the name, there is no formal workshop building standing here—only the shattered remains of an engineering endeavor and abandoned tools scattered across the sands.",al={"why deserted workshop","is there a workshop here","where is the workshop"}}},ang={["profession:Engineering"]="Every engineer who spots the crash site immediately recognizes the hallmark risks of experimental rocket fuel and overpowered thrusters pushing chassis far beyond safe tolerances.",["race:Gnome"]="Looking at the catastrophic collision, any gnomish tinkerer would suspect either reckless goblin corner-cutting or a wildly ambitious high-speed record attempt gone wrong."},kw={"crashed car","deserted workshop","gadgetzan","mirage raceway","rocket car","shimmering flats","tanaris","thousand needles"},rel={"subzone:gadgetzan","zone:tanaris","subzone:mirage-raceway","zone:thousandneedles"},src={"Deserted Workshop"}}
E["subzone:dunemaul-compound"] = {t="subzone",n="Dunemaul Compound",z="tanaris",s="Dunemaul Compound serves as the central settlement and ogre mound for the Dunemaul clan in Tanaris. Tucked into the rocky ridges bordering the desert wastes, it houses the clan's brute enforcers, spellcasters, and their chieftain, Sandscraper.",h="Dunemaul Compound serves as the central settlement and ogre mound for the Dunemaul clan in Tanaris.",sec={{t="A Stronghold in the Sands",b="Carved into the rugged desert rock of western Tanaris, the Dunemaul Compound is the primary stronghold of the Dunemaul ogres. These hulking desert dwellers have adapted to the harsh arid climate, scratching out an existence through brute force and opportunism. The compound itself centers on an ogre mound and cave network overseen by their leader, Sandscraper. Though primitive, the clan fields a dangerous mix of warriors, enforcers, and twisted spellcasters practicing dark warlock and mage magics. For travelers journeying across the dunes, the settlement is a treacherous den of aggressive giants who violently reject uninvited guests.",sp=0}},faq={{q="Who rules the Dunemaul Compound?",a="The compound is ruled by Sandscraper, the chieftain of the Dunemaul ogres. He resides deep within the central cave at the heart of the settlement, directing his clan's raids and defenses across the sands.",al={"dunemaul leader","who is sandscraper","dunemaul boss"}},{q="What kinds of ogres live here?",a="The settlement contains a wide variety of Dunemaul ogres, ranging from common brutes and enforcers to cunning ogre mages and warlocks wielding dark fel and shadow magic.",al={"dunemaul types","dunemaul mobs"}},{q="Why is the Horde interested in this compound?",a="Goblins aligned with the Horde operate a nearby post just to the east, aiming to strong-arm or negotiate with the Dunemaul clan to recruit their brute strength into the Horde's ranks.",al={"horde dunemaul","why recruit ogres","dunemaul recruitment"}},{q="Who is Omgorn the Lost?",a="Omgorn the Lost is an elusive, solitary ogre known to occasionally wander the edges of the Dunemaul Compound, distinct from the common sentries patrolling the mound.",al={"omgorn","rare ogre tanaris"}}},ang={["faction:Horde"]="The Horde maintains an active interest in the Dunemaul ogres, deploying agents just east of the compound in hopes of bending these stubborn desert giants into allied shock troops.",["class:Warlock"]="The presence of Dunemaul warlocks among a seemingly primitive desert clan is a curious sight, showing that shadow and fel traditions have taken root even within isolated ogre mounds."},kw={"dunemaul compound","dunemaul ogres","ogre mound","omgorn","sandscraper","tanaris"},rel={"zone:tanaris","subzone:dunemaul-recruitment-camp","subzone:southmoon-ruins","topic:horde"},src={"Dunemaul Compound"}}
E["subzone:dunemaul-recruitment-camp"] = {t="subzone",n="Dunemaul Recruitment Camp",z="tanaris",s="The Dunemaul Recruitment Camp is an outpost situated on the desert dunes of Tanaris, just east of the Dunemaul Compound. It serves as an effort by Horde emissaries and opportunistic goblin contractors to harness the brute strength of the local Dunemaul ogres.",h="The Dunemaul Recruitment Camp is an outpost situated on the desert dunes of Tanaris, just east of the...",sec={{t="Cheap Labor in the Dunes",b="While most wanderers view the Dunemaul ogres of Tanaris as little more than sun-baked brutes and highwaymen, goblin operatives see untapped economic potential. Positioned just outside the main Dunemaul Compound, this small encampment serves as a base to entice, bribe, or coerce the desert ogres into working directly under contractual oversight. By positioning intermediaries and envoys near the compound's edge, recruiters attempt to turn violent wasteland savages into profitable muscle for Horde endeavors.",sp=0}},faq={{q="What is the Dunemaul Recruitment Camp?",a="It is an outpost established just east of the Dunemaul Compound in Tanaris. Its primary function is to serve as a staging ground for recruiters seeking to bring local desert ogres into service as laborers and enforcers.",al={"dunemaul camp","recruitment camp tanaris","ogre recruitment camp"}},{q="Why are goblins and the Horde trying to recruit the Dunemaul ogres?",a="Ogres possess immense physical strength, making them ideal heavy laborers and shock troops. Rather than letting them simply raid desert caravans and squander their strength in isolation, enterprising recruiters aim to put them on the payroll as cheap, expendable muscle.",al={"why recruit dunemaul","why hire ogres"}},{q="Where is the camp located?",a="You can find it in western Tanaris, positioned right beside the dunes bordering the eastern side of the Dunemaul Compound.",al={"camp location","where is dunemaul recruitment camp"}}},ang={["faction:Horde"]="The camp reflects the Horde's pragmatic tradition of enlisting ogre clans for brute strength and heavy labor, bringing wild tribes under practical guidance."},kw={"bilgewater","compound","dunemaul","labor","ogres","recruitment camp","tanaris"},rel={"subzone:dunemaul-compound","zone:tanaris","topic:horde","subzone:maul-subzone"},src={"Dunemaul Recruitment Camp"}}
E["subzone:eastmoon-ruins"] = {t="subzone",n="Eastmoon Ruins",z="tanaris",s="The Eastmoon Ruins are an ancient troll archaeological site situated in eastern Tanaris, perched just west of the Gaping Chasm. Once built by the desert empires of old, the crumbling stone masonry is now occupied by opportunistic Wastewander bandits using the remnants as a desert encampment.",h="The Eastmoon Ruins are an ancient troll archaeological site situated in eastern Tanaris, perched just west of...",sec={{t="Stones in the Sand",b="Rising out of the blistering desert floor just west of the insect-infested Gaping Chasm, the Eastmoon Ruins preserve the crumbling architecture of ancient troll civilization. Decaying pillars, weathered stone plazas, and sun-bleached monuments hint at a time long before the sands swallowed this region. Rather than scholars or troll descendants tending the shrines, the site is firmly entrenched by the Wastewanders—human desert nomads and outlaws who rely on the broken walls for shelter and vantage over nearby trade routes.",sp=0}},faq={{q="Who built the Eastmoon Ruins?",a="The architecture belongs to ancient trolls. Long before Tanaris became an arid wasteland, troll civilizations dominated southern Kalimdor, leaving behind stone stonework, temples, and plazas like those weathering at Eastmoon.",al={"who made eastmoon ruins","eastmoon origin","trolls built eastmoon"}},{q="Who controls Eastmoon Ruins now?",a="The ruins are occupied by Wastewander bandits, including darkcasters, survivalists, and trackers. These human nomads have claimed the ancient stone walls to set up outposts and keep watch over eastern Tanaris.",al={"who lives at eastmoon","eastmoon ruins mobs","wastewanders at eastmoon"}},{q="Where are the Eastmoon Ruins located?",a="You can find them in the eastern reaches of Tanaris, situated immediately west of the silithid-infested hives of the Gaping Chasm.",al={"eastmoon ruins location","where is eastmoon","find eastmoon ruins"}},{q="Are there any quests in Eastmoon Ruins?",a="There are no formal quests directed specifically to the Eastmoon Ruins. The site serves primarily as a bandit camp and a historical landmark for adventurers exploring the deeper desert.",al={"eastmoon quests","quests at eastmoon ruins","is there a quest here"}}},ang={["race:Troll"]="The ruined masonry is a quiet reminder of your ancestors' far-reaching dominion over Kalimdor before the desert sands claimed the south.",["class:Rogue"]="The broken pillars and scattered stone walls provide plenty of blind corners to slip past or ambushing the Wastewander scouts roaming the perimeter."},kw={"darkcaster","eastmoon","eastmoon ruins","gaping chasm","survivalist","tanaris","troll ruins","wastewander"},rel={"zone:tanaris","subzone:gaping-chasm","topic:troll"},src={"Eastmoon Ruins"}}
E["subzone:gadgetzan"] = {t="subzone",n="Gadgetzan",z="tanaris",s="Gadgetzan is the walled desert hub of the Steamwheedle Cartel, standing as an island of commerce in northern Tanaris. Open to both Horde and Alliance travelers, the town operates under strictly enforced goblin neutrality, welcoming anyone with coin to spend or odd jobs to undertake.",h="Gadgetzan is the walled desert hub of the Steamwheedle Cartel, standing as an island of commerce in northern...",sec={{t="A Bastion of Profit in the Dunes",b="Surrounded by scorching sands, Gadgetzan serves as the regional heart for the Steamwheedle Cartel's ventures in southern Kalimdor. Built with characteristic goblin ingenuity and haphazard architecture, the town boasts an independent auction house, bank, inn, and specialized crafting facilities for engineers, blacksmiths, and alchemists. It also houses flight masters catering to both major factions, ensuring steady traffic of adventurers heading toward Tanaris, Feralas, and the untamed basin of Un'Goro. Above all, commerce rules supreme: as long as visitors keep their weapons sheathed and their purses open, they are safe within its gates.",sp=0},{t="Desert Troubles and Enforced Order",b="Peace in Gadgetzan is maintained not by good will, but by heavily armed goblin bruisers who swiftly pummel anyone who threatens trade or instigates faction brawls. Beyond the gates, however, life is precarious. The Gadgetzan Water Company constantly battles the Wastewander bandits, a ruthless gang occupying the vital Waterspring Field. Water is liquid gold in Tanaris, and the cartel frequently hires outside mercenaries to eliminate bandit leadership and reclaim vital water pouches to keep the town's reservoirs functional.",sp=0}},faq={{q="Can Alliance and Horde attack each other in Gadgetzan?",a="No. Gadgetzan is strictly neutral territory owned by the Steamwheedle Cartel. Goblin bruisers heavily patrol the town and will immediately attack anyone caught disturbing the peace or initiating violence against other travelers.",al={"is gadgetzan safe","pvp in gadgetzan","can horde and alliance fight here"}},{q="Why is water such a big deal around here?",a="Situated in the middle of an arid desert, Gadgetzan relies entirely on the Gadgetzan Water Company's extraction towers at Waterspring Field. Wastewander bandits have overrun these wells, cutting off the town's primary supply and forcing the goblins to pay bounties for stolen water pouches.",al={"gadgetzan water company","why water pouches","waterspring field conflict"}},{q="Who controls Gadgetzan?",a="Gadgetzan is owned and governed by the Steamwheedle Cartel, the largest and most prominent mercantile goblin organization on Azeroth.",al={"who runs gadgetzan","gadgetzan faction","what cartel owns gadgetzan"}},{q="What makes the auction house here special?",a="Unlike the faction-restricted markets in Orgrimmar or Stormwind, Gadgetzan hosts a neutral auction house. Both Alliance and Horde players can buy and sell goods to one another here, though the goblins charge a much higher transaction fee for the privilege.",al={"gadgetzan auction house","neutral auction house","cross faction ah"}}},ang={["profession:Engineering"]="Gadgetzan is an essential crossroads for tinkerers, hosting advanced trainers, specialized schematics, and an arrival teleportation pad calibrated specifically for gnomish engineers.",["profession:Blacksmithing"]="The town features heavy-duty forges and anvils favored by advanced metalworkers, serving as a key staging ground for members of the Mithril Order."},kw={"auction house","gadgetzan","goblin","neutral","steamwheedle cartel","tanaris","wastewander","waterspring field"},rel={"topic:steamwheedle-cartel","zone:tanaris","subzone:waterspring-field","subzone:road-warrior","zone:ungoro","topic:goblin","subzone:ratchet"},src={"Gadgetzan"}}
E["subzone:gaping-chasm"] = {t="subzone",n="Gaping Chasm",z="tanaris",s="The Gaping Chasm is a sprawling silithid hive carved deep into the sands of southeastern Tanaris. Infested by aggressive insectoid horrors of the Hazzali brood, it serves as a grim warning of the growing silithid menace spreading beyond the western deserts.",h="The Gaping Chasm is a sprawling silithid hive carved deep into the sands of southeastern Tanaris.",sec={{t="The Hive in the Dunes",b="Breaking the rolling expanses of Tanaris, the Gaping Chasm plunges down into a teeming subterranean warren of tunnels, resinous mounds, and twitching carapaces. This hive belongs to the Hazzali, an aggressive brood of silithid that have burrowed beneath the desert wastes. Between subterranean stingers, swarmers, and hulking sandreavers, any travelers or treasure-hunters foolish enough to descend into the chasm quickly find themselves hunted as prey or preserved in sticky cocoons.",sp=0},{t="A Surveyor's Grave",b="The expanding hive caught the attention of Gadgetzan's enterprising minds, prompting Senior Surveyor Fizzledowser to dispatch his junior surveyor, Scrimshank, into the pit to map and measure the geological shifts caused by the insect tunnels. Unsurprisingly, the expedition ended in disaster. Scrimshank met a grim end amidst the chittering broods, leaving behind scattered gear and measuring instruments that caution anyone against underestimating the silithid threat.",sp=0}},faq={{q="What creatures dwell inside the Gaping Chasm?",a="The chasm is infested entirely by the Hazzali silithid. The hive includes numerous castes of the insectoid species, such as worker drones, winged stingers, overwhelming swarms, and massive, chitin-plated sandreavers.",al={"what lives in gaping chasm","bugs in tanaris chasm","gaping chasm mobs"}},{q="Where is the Gaping Chasm located?",a="The chasm lies in southeastern Tanaris, carved out of the desert sands south of Gadgetzan and east of the mountainous ridge dividing Tanaris from the western wilderness.",al={"where is gaping chasm","gaping chasm location","how to find gaping chasm"}},{q="Why was a gnome surveyor sent into the chasm?",a="Senior Surveyor Fizzledowser in Gadgetzan sent Junior Surveyor Scrimshank to survey the cavern and assess its geological activity. Unfortunately, Scrimshank was overwhelmed and killed by the Hazzali silithid before he could complete his assignment.",al={"who was scrimshank","fizzledowser surveyor quest","why did scrimshank go there"},sp=1},{q="Are the silithid here related to the ones in other parts of Kalimdor?",a="Yes. The Hazzali silithid in Tanaris share the same insectoid nature and hive-mind structure as broods found in the southern barrens and the blighted wastes of Silithus to the west, signaling a dangerous, coordinated expansion across southern Kalimdor.",al={"are these silithid connected to silithus","why are bugs in tanaris"}}},ang={["race:Gnome"]="The unfortunate demise of Junior Surveyor Scrimshank inside the chasm serves as a sobering reminder that field research in Kalimdor demands serious firepower alongside scientific curiosity.",["profession:Mining"]="The exposed subterranean clefts and sunken earth of the silithid hive occasionally reveal rich mineral deposits, though digging them out requires fending off dozens of vicious burrowing insects."},kw={"fizzledowser","gaping chasm","hazzali","hive","sandreaver","scrimshank","silithid","tanaris"},rel={"zone:tanaris","subzone:gadgetzan","npc:senior-surveyor-fizzledowser"},src={"Gaping Chasm"}}
E["subzone:land-s-end-beach"] = {t="subzone",n="Land's End Beach",z="tanaris",s="Land's End Beach is a desolate stretch of coastline at the far southern tip of Tanaris, effectively marking the southern edge of Kalimdor. Shielded by towering mountain ridges and vast ocean waters, it remains one of the most secluded and inaccessible shores on the continent.",h="Land's End Beach is a desolate stretch of coastline at the far southern tip of Tanaris, effectively marking...",sec={{t="The Edge of the World",b="Tucked away behind the southern mountain ranges of Tanaris and the sealed titan gateway to Uldum, Land's End Beach represents the absolute southern edge of Kalimdor's mainland. Cut off from overland routes across the desert dunes, reaching this windswept coast requires swimming along the dangerous, fatigue-inducing open waters of the South Seas. The beach is a barren frontier of crashing surf, shifting sand, and quiet isolation, largely untamed by the cartels or desert explorers who dwell farther north around Gadgetzan.",sp=0},{t="Offshore Mysteries",b="Beyond the breakers of the beach lie lonely, unnamed islets separated from the mainland by vast expanses of exhausting deep water. Navigating to these distant specks of rock is treacherous enough to push even seasoned swimmers to their physical limits. Few mortals have any reason to seek out the lonely waters at Kalimdor's end, leaving the beach and its surrounding shoals undisturbed beneath the blazing southern sun.",sp=0}},faq={{q="Where is Land's End Beach located?",a="Land's End Beach is located along the southernmost coast of Tanaris, directly south of the mountains that seal off the ancient titan gates of Uldum at the far southern tip of Kalimdor.",al={"where is lands end beach","lands end beach location","how to find lands end beach"}},{q="How do you reach Land's End Beach?",a="Because massive mountain ranges block overland access from the desert interior, travelers typically must swim along the southern coastline from eastern Tanaris or navigate around the perilous open waters, being careful not to succumb to fatigue in the deep sea.",al={"how do i get to lands end beach","get to lands end tanaris","reach lands end"}},{q="What is on the islands off the coast of the beach?",a="Remote, unnamed islands sit far off the shoreline across a wide channel of deep, fatigue-inducing ocean. They are desolate rocky spits that very few travelers have ever reached or explored.",al={"unnamed islands lands end","offshore islands tanaris","islands near lands end"}},{q="Does anyone live on Land's End Beach?",a="The shoreline is uninhabited by any major settlements. Cut off from trade and civilization, it remains a barren natural shore buffeted by the ocean winds.",al={"who lives at lands end","lands end beach inhabitants","is anyone at lands end"}}},kw={"beach","coast","kalimdor","land's end beach","shore","south seas","tanaris","uldum"},rel={"zone:tanaris","subzone:uldum","subzone:gadgetzan"},src={"Land's End Beach"}}
E["subzone:lost-rigger-cove"] = {t="subzone",n="Lost Rigger Cove",z="tanaris",s="Tucked away along the eastern cliffs of Tanaris, Lost Rigger Cove serves as the primary base of operations for the Southsea Pirates in the region. Shielded by towering desert mountains on three sides, this hidden port boasts docks, fortified encampments, and an active shipyard constructing new pirate vessels.",h="Tucked away along the eastern cliffs of Tanaris, Lost Rigger Cove serves as the primary base of operations...",sec={{t="Pirates and Mountain Walls",b="Naturally fortified by sheer rock walls on almost every side, Lost Rigger Cove provides the Southsea Freebooters an ideal maritime stronghold on Kalimdor's southeastern edge. Here, pirate cutthroats, dockworkers, and brigands haul salvage and assemble fresh hulls right under the noses of Gadgetzan's authorities. The cove allows the Southseas to project power across the Great Sea while raiding trade routes between Ratchet, Booty Bay, and coastal settlements.",sp=0},{t="Goblin and Gnome Ambition",b="The pirates do not hold their cove unchallenged. Outside the cove's narrow pass, competing emissaries—a goblin and a gnome—have established a contentious forward camp. Both are vying for lucrative favors and commercial contracts from the Steamwheedle bosses in Gadgetzan by hiring out mercenaries to slaughter the Southseas, thin their ranks, and sabotage their shipbuilding operations.",sp=0}},faq={{q="Who controls Lost Rigger Cove?",a="The cove is held by the Southsea Pirates, an infamous maritime syndicate operating throughout Kalimdor and the South Seas. They use this natural harbor to repair their fleet and construct new warships.",al={"who owns lost rigger cove","who lives in lost rigger cove","lost rigger cove factions"}},{q="Why are gnomes and goblins camped outside?",a="Representatives from both races are attempting to win favor and trade deals with Baron Noggenfogger and the leaders of Gadgetzan. Each hopes to impress the goblin authorities by organizing strikes against the pirate stronghold.",al={"gnome goblin camp tanaris","why are gnomes here","why fight the pirates"}},{q="Where is Lost Rigger Cove located?",a="It lies along the eastern coast of Tanaris, southeast of Gadgetzan. It is accessed through a winding canyon path cut through the coastal mountain barrier.",al={"where is lost rigger cove","how to get to lost rigger cove","lost rigger cove map"}},{q="What are the pirates building in the cove?",a="The Southsea Pirates operate an active drydock and shipyard in the center of the cove, where carpenters and brigands are busy assembling the hull of a large ocean-going war vessel.",al={"shipyard lost rigger cove","pirate boat construction"}}},ang={["class:Rogue"]="The sprawling pirate camp is dense with pockets to pick, private lockboxes, and cutthroats who know every dirty trick of maritime swashbuckling.",["race:Gnome"]="Gnomish operatives stationed near the entrance are eager to demonstrate technological superiority over their goblin competitors by dismantling the Southsea operations."},kw={"freebooter","gadgetzan","lost rigger cove","shipyard","southsea pirates","tanaris"},rel={"zone:tanaris","subzone:gadgetzan","subzone:southbreak-shore","topic:gnome","topic:goblin","topic:pirate"},src={"Lost Rigger Cove"}}
E["subzone:noxious-lair"] = {t="subzone",n="Noxious Lair",z="tanaris",s="The Noxious Lair is a sunken silithid hive situated in the southwestern deserts of Tanaris, bordering Un'Goro Crater. Once a verdant basin with flowing water, the territory has been infested and drained of its vital resources by the burrowing Centipaar swarm. Now, it stands as an acidic breeding ground filled with swarming insectoids and rich mineral veins.",h="The Noxious Lair is a sunken silithid hive situated in the southwestern deserts of Tanaris, bordering Un'Goro...",sec={{t="A Drained Basin",b="Resting against the western ridges overlooking Un'Goro Crater, the Noxious Lair occupies a depression in the sand that once held a lake or shallow river. When the Centipaar silithid invaded, they consumed the desert's remaining underground moisture and transformed the basin into an encroaching colony. Vast pincers and twitching limbs rise directly from the sand dunes, surrounding subterranean tunnels slick with corrosive insect secretions and clusters of incubating eggs.",sp=0},{t="The Centipaar Swarm",b="Subterranean tunnels link the surface entrances to humid, acid-coated breeding chambers beneath the sands. Centipaar workers, tunnelers, wasps, and colossal sandreavers patrol the perimeter, defending their brood from outside threats. Beyond its biological dangers, the upheaval caused by silithid excavation has unearthed deep mineral deposits, creating an unusually diverse hunting and prospecting ground where subterranean ores sit exposed amid the swarming hives.",sp=0}},faq={{q="What kind of creatures live in the Noxious Lair?",a="The lair is populated by the Centipaar, a colony of the insectoid silithid. The hive is defended by workers, burrowing tunnelers, flying wasps, and predatory sandreavers, all guarded under the rule of rare hive terrors like Soriid the Devourer and Ainamiss the Hive Queen.",al={"what mobs are in noxious lair","noxious lair insects","centipaar silithid"}},{q="What was here before the silithid took over?",a="The sunken topography indicates that the area was once a riverbed or shallow desert lake. The arriving silithid burrowed beneath the earth, drained western Tanaris of its vital water and natural resources, and left behind a desolate, acid-soaked basin.",al={"noxious lair history","was noxious lair a lake","water in noxious lair"}},{q="Why are goblins interested in this hive?",a="Gadgetzan goblins view the hive as both a hazard to desert commerce and a profitable venture. Beast wranglers and gamblers have captured specimens here—such as Sarinexx—to pit them against challengers in the Thunderdrome arena, while others investigate egg gathering and silithid expansion.",al={"goblin quests noxious lair","steamwheedle noxious lair","thunderdrome silithid"}},{q="Is the Noxious Lair connected to other insect hives in the desert?",a="The Noxious Lair represents the Centipaar hive, one of several insectoid colonies spreading out from the southern wastes. While physically distinct from hives farther south, its tunnels share the same eerie subterranean architecture and threaten to choke out life across Tanaris.",al={"other hives tanaris","centipaar hive connection","silithid expansion"}}},ang={["profession:Mining"]="The silithid burrowing in the basin has exposed an unusually diverse selection of ore, letting miners gather Iron, Mithril, Truesilver, and Thorium veins in the same territory.",["class:Druid"]="The hive is a disturbing perversion of nature, demonstrating how quickly the invasive silithid can drain a once-watered basin into an arid, acidic wasteland."},kw={"ainamiss","centipaar","hive","noxious lair","sandreaver","silithid","soriid","tanaris"},rel={"zone:tanaris","zone:ungoro","topic:goblin"},src={"Noxious Lair"}}
E["subzone:road-warrior"] = {t="subzone",n="Road Warrior",z="tanaris",s="The Road Warrior is the bustling, shaded tavern of Gadgetzan in northern Tanaris. Managed by Innkeeper Fizzgrimble, it offers dusty mercenaries, engineers, and desert wanderers a cool drink and a brief sanctuary from the baking sands outside.",h="The Road Warrior is the bustling, shaded tavern of Gadgetzan in northern Tanaris.",sec={{t="A Tavern in the Wastes",b="Tucked safely within the fortified walls of Gadgetzan, the Road Warrior is the beating heart of hospitality in Tanaris. Run by the goblin Innkeeper Fizzgrimble, the establishment welcomes Alliance and Horde adventurers alike under the neutral peace enforced by Steamwheedle muscle. Inside its shaded walls, thirsty travelers can wash down the gritty desert sand with the house specialty, Mechs on the Beach, swap stories about the surrounding perils of the Southsea pirates and the Wastewander bandits, or set down their hearthstones before braving the scorching dunes.",sp=0}},faq={{q="What is the Road Warrior?",a="The Road Warrior is the primary inn and tavern in Gadgetzan, the bustling goblin trading hub located in Tanaris. It serves as a neutral rest stop for adventurers traversing the desert.",al={"what is road warrior","gadgetzan inn name","tanaris tavern"}},{q="Who runs the Road Warrior inn?",a="The inn is operated by Innkeeper Fizzgrimble, a goblin proprietor who happily sells rooms, refreshments, and hearthstone ties to anyone with coin, regardless of their faction allegiance.",al={"who is the innkeeper","fizzgrimble","innkeeper gadgetzan"}},{q="What drinks or specialties are served here?",a="The tavern's best-known concoction is the Mechs on the Beach, a popular local specialty favored by travelers looking to wash down the dry grit of the Tanaris wastes.",al={"mechs on the beach","road warrior drink","tavern drink"}},{q="Can Horde and Alliance both use this inn?",a="Yes. Because Gadgetzan is operated by the Steamwheedle Cartel, the Road Warrior is strictly neutral territory. Members of both factions can bind their hearthstones and rest under the watchful eyes of the Bruisers.",al={"is it neutral","can alliance rest here","can horde use inn"}}},ang={["profession:Cooking"]="For culinarians traveling the desert, the Road Warrior is an essential stop to purchase provisions, quench their thirst, and sample local tastes like the Mechs on the Beach."},kw={"fizzgrimble","gadgetzan","innkeeper","mechs on the beach","road warrior","tanaris","tavern"},rel={"subzone:gadgetzan","zone:tanaris"},src={"Road Warrior"}}
E["subzone:ruins-of-uldum"] = {t="subzone",n="Ruins of Uldum",z="tanaris",s="Tucked into the jagged cliffs of the Valley of the Watchers in southern Tanaris, the Ruins of Uldum consist of an ancient stone antechamber guarding a sealed Titan facility. Massive stone doors and crumbling earthen constructs protect its secrets from grave robbers and curious explorers alike.",h="Tucked into the jagged cliffs of the Valley of the Watchers in southern Tanaris, the Ruins of Uldum consist...",sec={{t="The Antechamber of the Titans",b="Carved deep into the bedrock of southern Tanaris, the Ruins of Uldum appear to be an antechamber or grand threshold to a far larger, sealed subterranean complex. Inside, silent Sandstone Earthen stand sentinel alongside exposed titan machinery and an ancient relic known as the Antediluvean Chest. Although violent tremors long ago ripped the outer doorway open, internal cave-ins and massive stone barriers have kept the deeper tunnels inaccessible. The dormant earthen do not stir unless threatened or unless an intruder tampers directly with the antechamber's safeguarded relics.",sp=0},{t="Secrets of the Biosphere",b="According to ancient records and celestial watchers, Uldum was established by the Titans alongside facilities like Uldaman and Ulduar as a research site dedicated to modifying and monitoring the biosphere of Azeroth. When the Great Sundering tore the world apart ten thousand years ago, the earthen felt the agony of the world and retreated into these subterranean vaults to hibernate. Full access beyond the ruins' sealed inner threshold requires the lost Plates of Uldum, leaving the full extent of the facility locked away from modern surface-dwellers.",sp=1}},faq={{q="What is inside the Ruins of Uldum?",a="The ruins consist of an antechamber filled with dormant Sandstone Earthen, exposed titan machinery, and the Antediluvean Chest. The deeper tunnels leading further inside the complex are collapsed and blocked off by massive stone doors.",al={"what's in uldum","what is uldum tanaris","ruins of uldum interior"}},{q="Can players enter the main facility behind the door?",a="No. The inner entrance is permanently sealed and collapsed. Ancient watchers note that access to the deeper complex requires the lost Plates of Uldum, which cannot currently be used to bypass the barrier.",al={"can you open the door to uldum","how to get into uldum","open uldum door"}},{q="Why are the Sandstone Earthen standing still?",a="The Sandstone Earthen inside the ruins are malfunctioning and dormant. Having hibernated within the facility since the Great Sundering, they remain inert unless an outsider attacks them or disturbs the Antediluvean Chest.",al={"why are earthen friendly","why don't earthen attack","sandstone earthen passive"}},{q="What was Uldum built for?",a="Titan constructs such as the Stone Watcher of Norgannon describe Uldum as a research complex intended to study, sustain, and enhance Azeroth's biosphere, similar in origin to sites like Uldaman and Ulduar.",al={"why did titans build uldum","uldum purpose","lore of uldum"}},{q="What happens if someone opens the Antediluvean Chest?",a="Tampering with the chest triggers an ancient security mechanism, summoning a hostile construct known as the Antechamber Guardian to eliminate the trespasser.",al={"antediluvean chest trap","what guards the chest","antechamber guardian"}}},ang={["race:Dwarf"]="For dwarves tracing their lineage back to the earthen, Uldum represents one of the original titan crèches where their ancestors first rested following the Sundering.",["profession:Mining"]="The stonework and machinery of Uldum showcase titan craftsmanship that has endured thousands of years of tectonic pressure and desert decay without faltering."},kw={"antechamber guardian","antediluvean chest","earthen","tanaris","titans","uldum","valley of the watchers"},rel={"subzone:valley-of-the-watchers","zone:tanaris","topic:titan","subzone:uldaman"},src={"Ruins of Uldum"}}
E["subzone:sandsorrow-watch"] = {t="subzone",n="Sandsorrow Watch",z="tanaris",s="Sandsorrow Watch is a sprawling desert outpost located just west of Gadgetzan in Tanaris. While the surrounding dunes and ruins are overrun by hostile Sandfury trolls and their reanimated dead, an eastern watch tower serves as an outpost overlooking the waste.",h="Sandsorrow Watch is a sprawling desert outpost located just west of Gadgetzan in Tanaris.",sec={{t="A Precarious Perch",b="Situated directly west of the bustling goblin trading hub of Gadgetzan, Sandsorrow Watch is a grim borderland in the Tanaris desert. The broad expanse is dominated by the Sandfury tribe—also known as the Farraki trolls—who aggressively defend the arid territory alongside legions of shambling troll zombies. An elevated watch tower at the eastern edge anchors the position, providing a fortified vantage point amidst the encroaching desert wilderness and the hostile indigenous tribes.",sp=0},{t="Frontier Outpost",b="The eastern outpost has been secured as a neutral foothold overlooking the Sandfury lands. Travelers and artisans, including the blacksmith Trenton Lighthammer, operate within this small camp while keeping a wary eye on Farraki activities. The encampment even keeps captured Sandfury specimens securely caged for study and interrogation, demonstrating the volatile frontier tension between Tanaris's opportunistic settlers and the native sand trolls.",sp=0}},faq={{q="Where is Sandsorrow Watch located?",a="Sandsorrow Watch is located directly west of Gadgetzan in the northern desert plains of Tanaris. Travelers heading out through Gadgetzan's western gate will encounter it almost immediately.",al={"sandsorrow watch location","where is sandsorrow","how to get to sandsorrow watch"}},{q="Who controls Sandsorrow Watch?",a="The wider ruins and surrounding dunes are occupied by hostile Sandfury trolls and their undead minions. However, the eastern watch tower itself is maintained as a neutral frontier camp, frequented by independent travelers and artisans like the smith Trenton Lighthammer.",al={"who lives at sandsorrow","sandsorrow watch faction","who holds sandsorrow watch"}},{q="Why are there undead trolls at Sandsorrow Watch?",a="The Sandfury tribe practices dark necromantic arts and voodoo, frequently raising fallen Farraki warriors as Sandfury Zombies to guard their desolate territory and outposts across Tanaris.",al={"sandfury zombies","why troll zombies tanaris","sandsorrow zombies"}},{q="What threats can adventurers expect in the surrounding dunes?",a="The area is heavily patrolled by Sandfury Axe Throwers, Firecallers, and Hideskinners, alongside their reanimated troll zombies. Unprepared travelers venturing off the main path west of Gadgetzan can easily be overwhelmed by roving Farraki warbands.",al={"sandsorrow mobs","sandsorrow watch enemies","hostile trolls sandsorrow"}}},ang={["profession:Blacksmithing"]="The camp at the watch tower is home to Trenton Lighthammer, a talented smith positioned deep in the desert sands.",["race:Troll"]="Darkspear trolls will find no kinship here: the hostile Sandfury Farraki tribe views all outsiders as invaders to be crushed and raised as shambling corpses."},kw={"farraki","gadgetzan","sand troll","sandfury","sandsorrow","sandsorrow watch","tanaris","trenton lighthammer"},rel={"zone:tanaris","subzone:gadgetzan","topic:troll"},src={"Sandsorrow Watch"}}
E["subzone:south-seas"] = {t="subzone",n="South Seas",z="tanaris",s="The South Seas encompass the vast, sun-drenched waters separating the southern regions of Kalimdor and the Eastern Kingdoms. Lapping at the shores of Tanaris, Thousand Needles, and Stranglethorn Vale, these tropical expanses are famed for lucrative trade routes, perilous reefs, and brazen pirate crews.",h="The South Seas encompass the vast, sun-drenched waters separating the southern regions of Kalimdor and the...",sec={{t="A Swashbuckler's Frontier",b="Spanning southward beneath the Great Sea and the Maelstrom, the South Seas wash against the deserts of Tanaris and the lush jungles of Stranglethorn Vale. Since the Great Sundering shattered the primeval continent ten thousand years ago, this ocean has nurtured remote tropical islands, unique oceanic beasts, and independent merchant networks. Goblin shipping cartels, operating out of havens like Steamwheedle Port and Booty Bay, maintain tenuous shipping lanes across the waves. However, the waters remain notoriously lawless, crawling with corsairs, Bloodsail buccaneers, and predatory sea life that prey on any vessel daring to venture far from shore.",sp=0},{t="Hidden Depths and Distant Isles",b="Beyond the coastal trade lanes lies a patchwork of legendary islands and sunken perils. Notable lands scattered across the South Seas include the goblin homeland of Kezan, the ancient troll island of Zandalar, the outlaw stronghold of Plunder Isle, and the produce-rich shores of Tel'Abim. Yet merchant sailors must contend with far more than cutthroats; the deeper waters harbor colossal giant squids, primeval sea turtles, and lurking naga who guard ancient ruins swallowed by the waves. Navigating these waters demands seasoned captains, reliable charts, and substantial firepower.",sp=0}},faq={{q="What zones border the South Seas?",a="In southern Kalimdor, the South Seas form the coastlines of Tanaris and Thousand Needles, near the sealed gates of Uldum. Across the ocean to the east, they wash against the shores of Stranglethorn Vale and its outlying islands like Jaguero Isle and Yojamba Isle.",al={"where are south seas","south seas borders","what coast is south seas"}},{q="Who controls shipping in the South Seas?",a="No single faction rules the South Seas. The Steamwheedle Cartel controls the primary merchant traffic between Steamwheedle Port and Booty Bay, but they constantly contest the waters against rival pirate outfits such as the Bloodsail Buccaneers and the Southsea Freebooters.",al={"who runs south seas","south sea trade","ports in south seas"}},{q="What dangerous creatures live in these waters?",a="The open waves teem with hazards ranging from ravenous giant squids and coastal reef sharks to armored giant turtles. In the Second War, the Horde's Stormreaver clan even captured giant turtles native to these waters to refit them as naval submersibles. Islands in the region also harbor flesh-eating bloodwing bats and lurking naga patrols.",al={"south seas monsters","sea monsters tanaris","south sea creatures"}},{q="What notable islands lie out in the South Seas?",a="Renowned islands out in the deep waters include the goblin commercial center of Kezan, the pirate hub of Plunder Isle, the fruit-rich island of Tel'Abim, and Zandalar, the historic realm of the troll empire. Closer to the coasts lie smaller landmarks like Yojamba Isle and Jaguero Isle.",al={"islands in south seas","kezan zandalar south seas","south seas island list"}}},ang={["class:Rogue"]="The lawless South Seas are the lifeblood of pirate cartels and privateers, offering endless opportunities for scoundrels adept at boarding actions, smuggling contraband, and navigating cutthroat harbor politics.",["profession:Cooking"]="The exotic waters and coastal shores of the South Seas yield prized oceanic fish, giant squids, and the famous, sweet bananas shipped from isolated isles like Tel'Abim."},kw={"bloodsail","kezan","pirates","plunder isle","south seas","steamwheedle","stranglethorn","tanaris","tel'abim","zandalar"},rel={"zone:tanaris","subzone:steamwheedle-port","zone:stranglethorn","subzone:booty-bay","topic:pirate","topic:goblin","subzone:uldum","topic:war-of-the-ancients"},src={"South Seas"}}
E["subzone:southbreak-shore"] = {t="subzone",n="Southbreak Shore",z="tanaris",s="Southbreak Shore is a wide, sun-bleached expanse of sandy coastline stretching along the southeastern edge of Tanaris. Bordering the pirate haven of Lost Rigger Cove, its sands are dominated by roving buccaneers, scavenging shore crabs, and wandering sea giants.",h="Southbreak Shore is a wide, sun-bleached expanse of sandy coastline stretching along the southeastern edge of...",sec={{t="A Lawless Strand",b="Southbreak Shore forms the southern boundary of the Southsea Freebooters' operations in Tanaris. While the deeper harbor of Lost Rigger Cove shelters their main fleet and encampments, Southbreak Shore serves as an open flank where Captain Dreadbeard organizes his crews along the surf. The strand is far from empty, crawling with Duneshore Crabs and massive sea giants that roam out of the tides, seemingly cooperating with Dreadbeard's brigands through unknown means.",sp=0},{t="The Offshore Isle",b="Just beyond the breaking waves sits a tiny, isolated spit of sand. Inhabiting this lonely offshore islet is a solitary gnome named Winkey, who watches the coastline in complete quiet. Why she has chosen to make camp mere swimming distance from bloodthirsty pirates and hulking giants remains an enigma to travelers passing along the desert coast.",sp=0}},faq={{q="Where is Southbreak Shore?",a="Southbreak Shore is located along the far southeastern coast of Tanaris, situated immediately south of Lost Rigger Cove and east of the deep desert dunes.",al={"southbreak shore location","where is southbreak shore","southbreak beach tanaris"}},{q="Who controls Southbreak Shore?",a="The northern reaches of the beach are overrun by the Southsea Freebooters under the direct command of Captain Dreadbeard, while the rest is prowled by wild creatures and towering sea giants.",al={"who rules southbreak shore","pirates on southbreak shore","captain dreadbeard beach"}},{q="Who is Winkey and why is she on the island?",a="Winkey is a lone gnome who lives on a tiny offshore islet just past the surf. She offers no official tasks or explanation for her presence so close to hostile pirates and ocean hazards.",al={"winkey","gnome on southbreak shore island","offshore gnome tanaris"}},{q="Why are there sea giants along the beach?",a="Sea giants patrol the shallow tides along Southbreak Shore and appear to be aiding Captain Dreadbeard and his pirates, though exactly how the freebooters secured the loyalty or cooperation of these behemoths is unknown.",al={"sea giants southbreak shore","why are sea giants helping pirates"}}},ang={["race:Gnome"]="The presence of Winkey standing alone on a secluded spit of sand off this perilous coast is a peculiar sight that naturally draws the curiosity of passing gnomes.",["class:Rogue"]="The Southsea buccaneers scouring Southbreak Shore are ruthless competitors in maritime plunder, making their outposts prime territory for reconnaissance and opportunistic thievery."},kw={"dreadbeard","duneshore crab","lost rigger cove","sea giants","southbreak","southbreak shore","southsea","tanaris","winkey"},rel={"zone:tanaris","subzone:lost-rigger-cove","topic:pirate","topic:gnome"},src={"Southbreak Shore"}}
E["subzone:southmoon-ruins"] = {t="subzone",n="Southmoon Ruins",z="tanaris",s="The Southmoon Ruins are ancient stone remains situated in southern Tanaris, just north of the Valley of the Watchers. Long claimed by the brutish Dunemaul ogres, the crumbling stonework preserves remnants of the ancient troll civilization that dominated the desert before the sands swallowed it.",h="The Southmoon Ruins are ancient stone remains situated in southern Tanaris, just north of the Valley of the...",sec={{t="Stones in the Shifting Sands",b="Rising out of the blistering wastes of southern Tanaris, the Southmoon Ruins stand as a weathered testament to the ancient troll empires that once ruled Kalimdor's southern reaches. Like nearby Eastmoon and Noonshade, its stone pillars and altars have weathered thousands of years of wind and abrasive grit. The site has often served as a squalid camp for the Dunemaul ogres, who show little reverence for the craftsmanship of the past, using the ancient structures purely for shelter and territory.",sp=0},{t="Secrets Beneath the Rubble",b="While the architectural remnants are unmistakably trollish, the deeper mystery of Southmoon lies in what may be buried beneath. Ancient tablets found across Tanaris hint that long before the trolls settled here, older creators left their marks upon the earth. Scholars and archaeologists drawn toward the nearby Valley of the Watchers look at sites like Southmoon as keys to unraveling the continent's earliest beginnings, searching for relics and inscriptions lost among the desert sands.",sp=0}},faq={{q="Who originally built the Southmoon Ruins?",a="The Southmoon Ruins were built thousands of years ago by the ancient Farraki sand trolls, whose empire once dominated southern Kalimdor before the Great Sundering shattered the continent and turned the region into the arid expanse of Tanaris.",al={"who built southmoon","southmoon history","are these troll ruins"}},{q="Who inhabits the ruins currently?",a="The ruins have traditionally been occupied by the Dunemaul ogres, who wandered down into Tanaris and claimed various crumbling ancient outposts as their encampments, driving off other scavengers.",al={"who lives here","southmoon mobs","dunemaul at southmoon"}},{q="Why are archaeologists interested in these ruins?",a="Beyond their troll origins, ruins in southern Tanaris frequently conceal much older relics, including carvings and tablets believed to date back to the Titans. Historians and excavators search these sites hoping to recover ancient knowledge buried beneath centuries of sand.",al={"why do dwarves care","what is buried here","southmoon artifacts"}},{q="Where are the Southmoon Ruins located?",a="They lie in the southern half of Tanaris, situated northwest of the Valley of the Watchers and south of the central desert wastes.",al={"southmoon location","where is southmoon ruins","how to find southmoon"}}},ang={["race:Dwarf"]="Dwarven excavators look closely at any ruins bordering the Valley of the Watchers, ever watchful for inscriptions linked to Titan origins buried beneath the troll stonework.",["race:Troll"]="For Darkspear trolls, these broken columns are a sobering look at the fallen grandeur of their distant Farraki cousins, reduced to squalor beneath the desert sun."},kw={"dunemaul","farraki","ruins","southmoon","southmoon ruins","tanaris","valley of the watchers"},rel={"zone:tanaris","subzone:valley-of-the-watchers","topic:explorers-league","topic:troll","topic:titan"},src={"Southmoon Ruins"}}
E["subzone:steamwheedle-port"] = {t="subzone",n="Steamwheedle Port",z="tanaris",s="Steamwheedle Port is a bustling coastal outpost on the eastern shore of Tanaris, directly connected to Gadgetzan. Operated by the neutral Steamwheedle Cartel, it serves as an essential sea link to distant islands like Kezan while constantly warding off encroaching Southsea Pirates.",h="Steamwheedle Port is a bustling coastal outpost on the eastern shore of Tanaris, directly connected to...",sec={{t="A Gateway on the Shifting Sands",b="Tucked against the dunes along the South Seas, Steamwheedle Port offers the inland desert city of Gadgetzan a direct lifeline to maritime trade. Run by the Steamwheedle Cartel, the settlement bustles with dockhands, traders, and sea captains braving the treacherous waters. Supply vessels regularly ply the routes between here and distant goblin strongholds, including Kezan, bringing valuable mechanical components, luxuries, and raw materials into southern Kalimdor.",sp=0},{t="Pirates and Strange Scholars",b="Life on the port is far from peaceful. Just south along the coast lies Lost Rigger Cove, home to rampant Southsea Freebooters who regularly raid goblin shipping, steal cargo, and contest control of the coastline. Aside from haggling dockworkers and paranoid merchants trying to recover stolen shipments, the port also shelters unusual travelers, such as the enigmatic troll Yeh'kinya, who studies the ancient and ominous spirits of the world away from prying eyes.",sp=0}},faq={{q="Who controls Steamwheedle Port?",a="The settlement is built and administered by the Steamwheedle Cartel, the primary trade conglomerate of neutral goblins. As long as you maintain standing with Gadgetzan and the Cartel, both Alliance and Horde travelers are welcomed freely.",al={"who runs steamwheedle port","steamwheedle port faction","is steamwheedle port friendly"}},{q="Where do the ships from this port travel?",a="The port serves as the Cartel's maritime link across the South Seas, notably connecting to the island of Kezan and other regional trading hubs, though it does not operate public commercial passenger transports for adventurers.",al={"where do ships go from steamwheedle","steamwheedle port ferry"}},{q="Why are there so many pirates nearby?",a="The Southsea Freebooters established their base just south at Lost Rigger Cove. They frequently hijack incoming cargo, raid dock supplies, and pick off stragglers along the shoreline, making them the primary local threat to goblin trade.",al={"lost rigger cove pirates","southsea pirates tanaris"}},{q="Who is Yeh'kinya?",a="Yeh'kinya is an eccentric troll scholar resting at the port. He enlists daring adventurers to travel abroad, capturing spiritual essences such as screechers from Feralas to research forgotten, primordial rituals.",al={"yehkinya purpose","troll in steamwheedle port"}}},ang={["profession:Engineering"]="The port is an invaluable depot for parts and supplies imported directly from Kezan, making it a natural hub of gossip and schematics for tinkerers.",["class:Rogue"]="The constant friction between goblin merchants and the nearby Southsea Pirates creates lucrative opportunities for pickpockets, scouts, and recovery contracts."},kw={"gadgetzan harbor","kezan trade","lost rigger cove","southsea pirates","steamwheedle port","tanaris docks","yeh'kinya"},rel={"zone:tanaris","subzone:gadgetzan","topic:steamwheedle-cartel","subzone:lost-rigger-cove","npc:yeh-kinya","topic:pirate","subzone:south-seas","topic:goblin"},src={"Steamwheedle Port"}}
E["subzone:thistleshrub-valley"] = {t="subzone",n="Thistleshrub Valley",z="tanaris",s="Tucked away in the southwestern reaches of Tanaris, Thistleshrub Valley is a bizarre oasis of prickly plant life amidst endless dunes. The canyon is known for its strange grove of giant cacti and hostile animated thistleshrubs that attack anything stepping through their thorn-choked territory.",h="Tucked away in the southwestern reaches of Tanaris, Thistleshrub Valley is a bizarre oasis of prickly plant...",sec={{t="A Grove of Thorns",b="While most of Tanaris is an arid wasteland stripped bare of vegetation, Thistleshrub Valley is curiously choked with life. Giant blooming cacti tower over the canyon floor, providing a sharp contrast to the surrounding sea of sand. However, this is no peaceful sanctuary. The valley takes its name from the hostile, living plant creatures that lurk among the brush. These thistleshrubs lash out with razor-sharp spines at any traveler who wanders near, making navigation hazardous for those trying to push past the cliffs toward the mysterious southern gates.",sp=0},{t="Sentinels of the Desert",b="The presence of animated flora in such a dry climate has long puzzled wanderers and desert survivalists. Whether awakened by forgotten elemental energies or stubborn adaptation to the harsh Tanaris climate, the thistleshrubs remain violently territorial. Travelers journeying through the canyon must contend not only with these thrashing thickets of thorn and root, but also the desert predators and venomous serpents that nest among the towering cacti.",sp=0}},faq={{q="Where is Thistleshrub Valley located?",a="Thistleshrub Valley is nestled in the southwestern corner of Tanaris, wedged along the southern mountain ridge near the mysterious sealed gates of Uldum.",al={"thistleshrub valley location","where is thistleshrub","find thistleshrub valley"}},{q="Why is there so much plant life in this part of Tanaris?",a="Unlike the rest of the barren desert, the valley shelters a microclimate dominated by towering cacti and animated plant life. How these unusual thistleshrubs thrive so aggressively in the dry desert sand remains an enduring mystery of the southern dunes.",al={"why giant cactus here","why are plants growing here"}},{q="What creatures live in Thistleshrub Valley?",a="The valley is overrun by hostile, walking thistleshrub creatures, aggressive desert blooms, and various venomous reptiles that hide beneath the thorny vegetation.",al={"thistleshrub valley mobs","monsters in thistleshrub valley"}},{q="What is the massive stone structure near the valley?",a="Just beyond the valley sits a massive, sealed Titan structure often referred to as the gateway to Uldum, which remains locked and enigmatic to desert wanderers.",al={"doors near thistleshrub","titan gate tanaris"}}},ang={["profession:Herbalism"]="The valley is an anomaly for herbalists traversing Tanaris, hosting peculiar and resilient desert plant life among thick groves of thorny brush.",["class:Druid"]="Druids may find the viciously animated thistleshrubs fascinating, pondering what primeval or elemental forces keep them thriving in an otherwise desolate desert."},kw={"cacti","cactus","desert","tanaris","thistleshrub","thorns","uldum","valley"},rel={"zone:tanaris","subzone:uldum"},src={"Thistleshrub Valley"}}
E["subzone:uldum"] = {t="subzone",n="Uldum",z="tanaris",s="Uldum is a massive, sealed Titan research installation tucked behind colossal stone gates in the southernmost cliffs of Tanaris. Long hidden away behind ancient wards and forgotten machinery, it remains inaccessible to modern explorers, watched over by a lone dwarven prospector.",h="Uldum is a massive, sealed Titan research installation tucked behind colossal stone gates in the southernmost...",sec={{t="The Gates of the Makers",b="Carved into the rugged southern mountain range bordering the Tanaris desert, the monumental gateway to Uldum stands silent and impassable. Built during the ordering of ancient Kalimdor, the compound served as an advanced Titan facility tied to their mysterious efforts to shape and oversee the planet's biosphere. Titanic wardens and defensive constructs once maintained the perimeter, leaving modern mortals only monumental stone carved arches and buried secrets that have defied all mundane attempts at entry.",sp=0},{t="The Dwarven Vigil",b="Recognizing the site's unmistakable Titan craftsmanship, the Ironforge Explorers' League dispatched Prospector Gunstan to maintain a lonely watch over the entrance. For years, Gunstan has studied the monolithic doors and searched for a mechanism or key that might unlock the ancient complex. Legend claims that true insight into the secrets locked within requires the lost Plates of Uldum, leaving the dwarven scholars peering through the keyhole of an empire they cannot yet breach.",sp=0}},faq={{q="Can you open the gates to Uldum?",a="No. The massive stone gates leading into the mountain pass are completely sealed and shut fast against any mortal intrusion. No mechanism or key exists in the surrounding desert to unlock them.",al={"how to get into uldum","open uldum door","enter uldum"}},{q="What is inside Uldum?",a="According to ancient records and Titan lore, Uldum is a vast research facility constructed by the Titans to study and enhance the biosphere of Azeroth. However, exact details remain locked away behind Titan security measures.",al={"what is uldum","purpose of uldum","inside uldum"}},{q="Who is the dwarf standing outside the gate?",a="That is Prospector Gunstan, a field researcher sent by the Ironforge Explorers' League. He maintains a solitary camp right outside the threshold, observing the masonry and hoping to uncover a way inside.",al={"gunstan","prospector gunstan","dwarf at uldum"}},{q="What are the Plates of Uldum?",a="The Plates of Uldum are ancient data discs created by the Titans. According to lore preserved by ancient stone keepers, specific knowledge regarding the work and facilities inside Uldum can only be accessed through these sacred plates.",al={"plates of uldum","discs of uldum","uldum tablets"}}},ang={["race:Dwarf"]="For dwarves pursuing their Titan heritage through the Explorers' League, the colossal gates of Uldum represent one of the greatest uncracked mysteries on the continent of Kalimdor.",["faction:Alliance"]="The Alliance maintains a lone observational foothold through Prospector Gunstan, hoping to beat any rival power to whatever Titan secrets lie concealed in the southern mountains."},kw={"explorers' league","gates of uldum","gunstan","plates of uldum","tanaris","titans","uldum"},rel={"zone:tanaris","topic:titan","topic:explorers-league","zone:ungoro","zone:silithus","topic:alliance"},src={"Uldum"}}
E["subzone:valley-of-the-watchers"] = {t="subzone",n="Valley of the Watchers",z="tanaris",s="Tucked away in the far southern reaches of the Tanaris desert, the Valley of the Watchers is a sun-scorched canyon defined by monumental stonework. At its end stands a colossal, sealed stone gate leading into the mysterious complex of Uldum, guarded by lumbering giants and ancient stone sentinels.",h="Tucked away in the far southern reaches of the Tanaris desert, the Valley of the Watchers is a sun-scorched...",sec={{t="The Sealed Threshold",b="The Valley of the Watchers marks the southern boundary where the shifting sands of Tanaris meet the mountainous edge of the continent. Dominating the canyon is a massive gate crafted from ancient stone, locked tight against the outside world. This sealed portal is believed to guard the entrance to Uldum, a subterranean facility of the enigmatic Titans. Massive Dune Smasher mountain giants roam the dusty approach, ensuring that whatever secrets lie buried beneath the sands remain undisturbed by travelers, tomb robbers, and scholars alike.",sp=0}},faq={{q="What is behind the huge stone gate here?",a="The monumental doors are the entrance to Uldum, an ancient subterranean facility constructed by the Titans long before recorded mortal history. For now, the mechanisms remain entirely sealed, keeping its true contents and purpose a total mystery.",al={"gate of uldum","what is uldum","what is behind the door"}},{q="Can the gate to Uldum be opened?",a="No. The massive stone gates are completely impassable. No mortal key, spell, or force currently known in Kalimdor can bypass the Titan safeguards locking the complex shut.",al={"can you open the uldum gate","open uldum door","how to get into uldum"}},{q="Why are there giants wandering the valley?",a="Colossal mountain giants known as Dune Smashers prowl the canyon floor. Drawn to the area's potent earthen energy, they fiercely guard the approach, crushing any adventurers who stray too close to the southern cliffs.",al={"why are there dune smashers","valley giants","mountain giants tanaris"}},{q="Where in Tanaris is this valley located?",a="The valley lies at the far southern edge of Tanaris, south of the Thistleshrub Valley and the gaping chasms of the Southbreak Shores, carved directly into the towering southern mountain wall.",al={"valley of the watchers location","how to find valley of the watchers","where is the gate"}}},ang={["race:Dwarf"]="For dwarven explorers and members of the Explorer's League, the massive stone gateway represents another tantalizing puzzle piece in the search for their Titan creators."},kw={"dune smasher","kalimdor","tanaris","titan gate","titans","uldum","valley of the watchers"},rel={"zone:tanaris","subzone:uldum","topic:titan"},src={"Valley of the Watchers"}}
E["subzone:waterspring-field"] = {t="subzone",n="Waterspring Field",z="tanaris",s="Waterspring Field is a vital water-pumping operation in northern Tanaris, constructed by the goblins of Gadgetzan to tap underground aquifers. Instead of supplying the boomtown, the field has been overtaken by the ruthless Wastewander bandits, who now hoard the desert's most precious resource.",h="Waterspring Field is a vital water-pumping operation in northern Tanaris, constructed by the goblins of...",sec={{t="A Stolen Oasis",b="In the searing wastes of Tanaris, nothing carries more value than fresh water. Seeking to support their expanding trade hub, the Steamwheedle Cartel goblins of Gadgetzan erected an array of industrial pumping towers across Waterspring Field to draw from underground reserves. Their plans collapsed when the Wastewanders—a sprawling band of human outlaws and desert marauders—seized the entire field. The bandits now guard the hijacked pumps with their lives, forcing Gadgetzan to look for hired blades willing to reclaim the moisture.",sp=0}},faq={{q="Who built the water towers here?",a="The towers were built by the goblins of Gadgetzan. They intended to pump fresh water from deep subterranean reserves to sustain their desert settlement and industrial operations.",al={"who built this","goblin pumps","waterspring field towers"}},{q="Why are there bandits squatting at Waterspring Field?",a="The Wastewander nomads invaded the field and seized the machinery for themselves. Controlling the primary source of fresh water in northern Tanaris gives them total leverage over surrounding travelers and merchants.",al={"who are the bandits","wastewanders waterspring","why are wastewanders here"}},{q="Why doesn't Gadgetzan take the field back directly?",a="The Steamwheedle Cartel prefers to protect its own trade town rather than waste its bruised bruised Bruisers on bloody field skirmishes. They find it far more cost-effective to contract passing adventurers and mercenaries to cull the bandits and retrieve their water pouches.",al={"why gadgetzan no fight","goblin guards waterspring"}}},ang={["profession:Engineering"]="The goblin-built mechanical pumping towers represent impressive desert hydraulics, though the occupying Wastewanders have neglected regular maintenance.",["race:Human"]="The Wastewander bandits occupying the towers are predominantly human outlaws who have forsaken the kingdoms of the north to carve out a brutal existence in the desert sun."},kw={"gadgetzan","pumps","tanaris","wastewander","water pouches","water towers","waterspring field"},rel={"zone:tanaris","subzone:gadgetzan","topic:goblin"},src={"Waterspring Field"}}
E["subzone:wavestrider-beach"] = {t="subzone",n="Wavestrider Beach",z="tanaris",s="Wavestrider Beach is the sun-scorched coastal strip lining the eastern edge of Tanaris. Stretching between Steamwheedle Port and the pirate stronghold at Lost Rigger Cove, its sands are inhabited by aggressive crustacean wildlife and overlook distant naval skirmishes out at sea.",h="Wavestrider Beach is the sun-scorched coastal strip lining the eastern edge of Tanaris.",sec={{t="A Treacherous Coastline",b="Running along the ocean border of eastern Tanaris, Wavestrider Beach connects the goblin settlement of Steamwheedle Port in the north to the cliffs guarding Lost Rigger Cove to the south. Rather than a gentle resort, the shoreline is plagued by vicious Steeljaw Snappers and Desert Crawlers scuttling across the baking sand. Out in the deep water just offshore, burning vessels remain locked in a perpetual naval clash, serving as a grim warning of the piratical violence that dominates these coastal waters.",sp=0}},faq={{q="Where is Wavestrider Beach located?",a="Wavestrider Beach lies along the eastern coastline of Tanaris, stretching directly between the docks of Steamwheedle Port to the north and the mouth of Lost Rigger Cove to the south.",al={"wavestrider beach location","where is wavestrider beach","wavestrider beach tanaris"}},{q="What creatures wander the sands here?",a="The beach is primarily overrun by aggressive marine scavengers, including native Desert Crawlers and heavily armored Steeljaw Snappers prowling the surf.",al={"wavestrider beach mobs","crabs on wavestrider beach"}},{q="What are the burning ships visible offshore?",a="Looking out to sea from the beach, travelers can spot two blazing vessels engaged in ongoing combat. They reflect the rampant pirate activity that plagues the waters surrounding the Southsea Freebooters' hideouts.",al={"burning ships tanaris","ships on fire wavestrider beach"}},{q="Is Wavestrider Beach safe to travel through?",a="It is relatively hazardous. Between the aggressive snapjaws and crabs along the water's edge and its close proximity to Southsea pirate territory, unwary explorers can quickly find themselves overwhelmed.",al={"is wavestrider beach dangerous","wavestrider beach safety"}}},kw={"coast","desert crawler","lost rigger cove","southsea","steamwheedle port","steeljaw snapper","tanaris","wavestrider beach"},rel={"zone:tanaris","subzone:steamwheedle-port","subzone:lost-rigger-cove"},src={"Wavestrider Beach"}}
E["subzone:zalashji-s-den"] = {t="subzone",n="Zalashji's Den",z="tanaris",s="Zalashji's Den is a secluded cave tucked along the eastern coast of Tanaris. It serves as the solitary lair of Zalashji, an enigmatic naga who dwells far from the typical gathering grounds of his serpentine kin.",h="Zalashji's Den is a secluded cave tucked along the eastern coast of Tanaris.",sec={{t="A Solitary Lair",b="Carved into the rugged bluffs along the eastern shoreline of Tanaris, this coastal cavern provides shelter to a single inhabitant: Zalashji. Naga are known across Kalimdor to gather in disciplined war parties or coastal outposts, yet Zalashji resides here entirely alone. Little is known about why he made this isolated cave his domain, far removed from the primary settlements and desert ruins of the region, but any traveler venturing along the surf should approach the cave mouth with caution.",sp=0}},faq={{q="Where is Zalashji's Den located?",a="The cave is located on the eastern coastline of Tanaris, recessed into the rocky bluffs that border the ocean waters.",al={"zalashji location","where is zalashji den","zalashji cave"}},{q="Who is Zalashji?",a="Zalashji is an individual naga who makes this isolated coastal cavern his home, lingering along the desert shore away from larger naga forces.",al={"who is zalashji","zalashji lore","what is zalashji"}},{q="Are there any quests associated with this cave?",a="There are no known quests directing adventurers to Zalashji's Den. It remains a curious landmark for coastal explorers traveling the eastern perimeter of Tanaris.",al={"zalashjis den quests","is there a quest here","zalashji quest"}},{q="Why is a naga living alone in Tanaris?",a="His true motives remain unknown. While naga generally congregate near sunken ruins or organized encampments, Zalashji keeps to himself in this solitary seaside lair.",al={"why is zalashji alone","naga in tanaris","why is zalashji here"}}},ang={["race:NightElf"]="For the night elves, any presence of the cursed, mutated naga on Kalimdor's shores is a grim reminder of the ancient Highborne and the Sundering."},kw={"cave","coast","naga","tanaris","zalashji","zalashji's den"},rel={"zone:tanaris","topic:naga"},src={"Zalashji's Den"}}
E["subzone:zul-farrak"] = {t="subzone",n="Zul'Farrak",z="tanaris",s="Zul'Farrak is a sprawling, sun-baked sandstone city tucked into the northwestern cliffs of Tanaris. Long isolated from the rest of their kind, the Sandfury trolls defend this ancient stronghold with fanatic zeal, dark voodoo, and a hoard of undead risen from their sandy graves.",h="Zul'Farrak is a sprawling, sun-baked sandstone city tucked into the northwestern cliffs of Tanaris.",sec={{t="The Withered Remnant",b="Before the Great Sundering shattered ancient Kalimdor, Tanaris was a lush jungle belonging to the Gurubashi Empire, and Zul'Farrak was one of its prominent settlements. Severed from their brethren when the seas broke the world, the resident Farraki trolls adapted to the searing, arid wastes, transforming over millennia into the hardened sand trolls seen today. Desperate to reclaim lost prominence, their priests now practice a brutal brand of dark mysticism, exhuming their own dead to build a shambling army within their sun-bleached walls.",sp=0},{t="Legends of the Sand",b="Whispers throughout Gadgetzan tell of treasures and terrors hidden behind Zul'Farrak's guarded gates. Troll lore speaks of Sul'thraze the Lasher, a legendary broadsword broken into two separate blades that remain hidden somewhere in the city. More alarming are the tales of a band of mercenaries led by Sergeant Bly who wandered into the city and were captured, as well as rumors of Gahz'rilla, an ancient hydra demigod slumbering within a sacred pool at the city's heart.",sp=0}},faq={{q="What tribe of trolls lives here?",a="Zul'Farrak is held by the Sandfury tribe (also called the Farraki). They were once part of the southern Gurubashi Empire before the Great Sundering turned their lush home into a desert, forcing them to adapt to the scorching sands.",al={"who lives in zulfarrak","sand troll tribe","what trolls are these"}},{q="Why are there so many zombies and graves inside?",a="Pushed to the brink of desperation and isolation, the Sandfury witch doctors and shadow hunters have turned to dark necromancy. They have begun raising their fallen kin as undead thralls to bolster their ranks and wage war across Tanaris.",al={"why undead in zulfarrak","sandfury zombies","troll graves"}},{q="What is the ancient monster sleeping in the city?",a="The creature is Gahz'rilla, a colossal hydra demigod. Kept slumbering in a deep sacred pool within the city, it is revered by the Sandfury, though disturbing rumors suggest the beast can be called forth with the proper ritual instrument.",al={"hydra boss","ancient creature in pool","gahzrilla"}},{q="What is Sul'thraze the Lasher?",a="Sul'thraze the Lasher is a legendary blade from ancient troll folklore, renowned for sapping the strength and will of anyone struck by it. Long ago it was shattered into two distinct swords, Jang'thraze and Sang'thraze, both of which are rumored to be kept inside the city.",al={"sandfury sword","sulthraze","zul farrak sword legend"}}},ang={["race:Troll"]="The Sandfury view the Darkspear as weak traitors allied with foreign conquerors, while Darkspear elders like Master Gadrin watch their corrupted desert cousins with grim concern.",["faction:Alliance"]="Human and dwarven explorers are frequently drawn here to recover ancient relics or rescue missing mercenaries who vanished into the ruins from Gadgetzan."},kw={"farraki","gadgetzan","gahz'rilla","sand trolls","sandfury","sul'thraze","tanaris","zul'farrak"},rel={"zone:tanaris","subzone:gadgetzan","topic:troll","npc:master-gadrin","subzone:sen-jin-village","quest:1179","subzone:mirage-raceway","subzone:tabetha-s-farm"},src={"Zul'Farrak"}}
E["topic:arthas-menethil"] = {t="topic",n="Arthas Menethil",z="tanaris",s="Once the golden prince of Lordaeron and a celebrated paladin of the Silver Hand, Arthas Menethil fell from grace during the Third War while pursuing the demonic orchestrators of the plague. After claiming the cursed runeblade Frostmourne in the frozen north, he surrendered his soul, murdered his father King Terenas, and spearheaded the destruction of his own homeland as the Scourge's dark champion.",h="Once the golden prince of Lordaeron and a celebrated paladin of the Silver Hand, Arthas Menethil fell from...",sec={{t="The Golden Prince",b="Born to King Terenas Menethil II, Arthas was raised to embody the ideals of the Alliance of Lordaeron. Trained in combat by Muradin Bronzebeard and inducted into the Order of the Silver Hand under the tutelage of Uther the Lightbringer, he was revered by high and low alike as the future of humanity. Bold, skilled, and fiercely protective of his people, he fought tenaciously against Blackrock clan orc incursions and forest troll warbands. Yet beneath his radiant exterior lay an uncompromising pride and an obsessive dread of failure.",sp=0},{t="The Scourge and the Culling",b="When the mysterious Plague of Undeath gripped northern Lordaeron, Arthas raced across the countryside alongside the sorceress Jaina Proudmoore to stem its spread. Tracing the tainted grain from Brill to Andorhal, he slew the necromancer Kel'Thuzad, only to discover a vast conspiracy orchestrated by the dreadlord Mal'Ganis. Confronting the infected populace at Stratholme, Arthas chose pragmatic cruelty over moral restraint, commanding the wholesale slaughter of the city's inhabitants before they could turn. Repulsed by his madness, Uther and Jaina abandoned him as the city burned.",sp=1},{t="The Fall and Ascendance",b="Fixated on vengeance, Arthas tracked Mal'Ganis to the frozen wastes of Northrend. There he reunited with Muradin and uncovered the runeblade Frostmourne, ignoring its dreadful curse to defeat the demon. The blade severed Arthas's soul, leaving him a puppet of the Lich King. Returning to Capital City as a Death Knight, Arthas drove the runeblade through his father's heart and drowned Lordaeron in ash and undeath. He crushed the Silver Hand, obliterated Dalaran, and carved a bloody path through Quel'Thalas before journeying back to the Frozen Throne to fuse directly with his dark master.",sp=2}},faq={{q="Who was Arthas Menethil before his fall?",a="Arthas was the Crown Prince of the Kingdom of Lordaeron and heir to King Terenas Menethil II. He was inducted into the Knights of the Silver Hand at nineteen and was widely considered one of the finest young paladins and swordsmen of the realm.",al={"arthas backstory","who was prince arthas","arthas prince of lordaeron"}},{q="Why did Arthas purge Stratholme?",a="The city's citizens had already consumed grain contaminated by the Plague of Undeath, ensuring they would rise as mindless undead under Mal'Ganis's control. Believing mercy was impossible, Arthas ordered the immediate slaughter of the entire populace to prevent an army of Scourge from rising.",al={"why did arthas cull stratholme","culling of stratholme","stratholme purge"}},{q="How did Arthas become corrupted?",a="Obsessed with destroying Mal'Ganis, Arthas journeyed to Northrend and claimed Frostmourne, a cursed runeblade forged by the Lich King. The blade drained his soul and bound his mind to Ner'zhul, transforming him into the vanguard death knight of the Scourge.",al={"how did arthas turn evil","arthas corruption","why did arthas become death knight"}},{q="What happened to King Terenas?",a="After succumbing to Frostmourne, Arthas returned to Capital City under the guise of a returning conqueror. In the throne room, amid ringing bells and falling rose petals, he drew his runeblade and impaled his own father.",al={"arthas kills father","death of king terenas","what happened to terenas"}},{q="What was Arthas's relationship with Jaina Proudmoore?",a="They were close companions from childhood who later shared a mutual romance during their youth. Arthas ended their formal courtship to prioritize duty, though they remained deeply bonded until his descent into cruelty at Stratholme drove her away.",al={"arthas and jaina","did jaina love arthas","arthas romance"}},{q="Where is Arthas right now?",a="Following the defense of the Frozen Throne against the demon hunter Illidan, Arthas ascended Icecrown, shattered the icy prison of the Lich King, and merged his essence with Ner'zhul, ruling the Scourge from Northrend.",al={"where is arthas","current status of arthas","is arthas alive"}}},ang={["class:Paladin"]="Arthas is the greatest tragedy and shame of the Silver Hand; his fall corrupted the very tenets of justice and protection that Uther strove to instill.",["race:Human"]="The destruction of Lordaeron broke the human race in two, scattering refugees across the globe and leaving Stormwind as humanity's final great seat of power.",["race:Undead"]="The Forsaken view Arthas with unmatched hatred, having broken free from the dark prince's mental thrall under Queen Sylvanas to seek vengeance for their damnation.",["faction:Alliance"]="Arthas's treason cost the Alliance of Lordaeron its greatest kingdom, its capital city, and the legendary paladin order that once anchored human faith."},kw={"arthas","frostmourne","lich king","lordaeron","menethil","scourge","stratholme","terenas"},rel={"topic:scourge","topic:lich-king","subzone:stratholme","topic:terenas-menethil-ii","npc:jaina-proudmoore","topic:muradin-bronzebeard","topic:plague-of-undeath","topic:lordaeron"},src={"Arthas Menethil"}}
E["zone:tanaris"] = {t="zone",n="Tanaris",z="tanaris",s="Tanaris is a vast, sweltering desert spanning the southern reaches of Kalimdor, defined by rolling sand dunes and blistering heat. At its heart lies Gadgetzan, a neutral trading outpost operated by the goblins of the Steamwheedle Cartel. Beyond the bustling settlements, the dunes conceal hostile sand trolls, dangerous silithid hives, and the hidden domain of the bronze dragonflight.",h="Tanaris is a vast, sweltering desert spanning the southern reaches of Kalimdor, defined by rolling sand dunes...",sec={{t="A Sea of Dunes",b="Before the Great Sundering shattered the world, this expanse was a lush jungle settled by early tauren and claimed by the Gurubashi Empire. The cataclysm stripped the land of its canopy, leaving a barren, sun-scorched wilderness. Stranded by the shifting geography, the local trolls adapted into the hardened Sandfury tribe, carving out their isolated empire within the walled city of Zul'Farrak. Today, the desert floor is ruled by hyenas, basilisks, and scorpids, while subterranean tunnels snake beneath the baking earth.",sp=0},{t="Goblin Enterprise",b="Because Tanaris is as close to their island homeland of Undermine as the mainland allows, the Steamwheedle Cartel has established a thriving enterprise here. From the walled oasis of Gadgetzan to the coastal docks of Steamwheedle Port, the goblins maintain strict neutrality, welcoming coin from both the Alliance and the Horde. Their peace is maintained by heavy bruiser muscle, though rogue threats like the Southsea Freebooters constantly harass shipping and dig sites along the coastline.",sp=0},{t="Ancient Mysteries and Rising Perils",b="The sands hide powers far older than mortal empires. In the eastern reaches lie the Caverns of Time, the ancestral domain of Nozdormu and his bronze dragonflight, whose drakes can occasionally be seen riding the desert thermals. To the south, massive stone gates mark the titan complex of Uldum. Yet a darker danger stirs from subterranean nests like the Gaping Chasm and the Noxious Lair, where creeping silithid swarms have begun burrowing outward across the sands.",sp=0}},faq={{q="How do I travel to Tanaris?",a="Travelers must journey through Thousand Needles into the Shimmering Flats. A mountain pass carved through the cliffs at the southern end of the salt flats leads directly down into the desert, bringing you immediately within sight of Gadgetzan's walls.",al={"how to get to tanaris","getting to tanaris","tanaris entrance"}},{q="Why is Gadgetzan neutral to both factions?",a="Gadgetzan is governed by the Steamwheedle Cartel, whose sole allegiance is to profit. To maximize commerce and protect trade routes across the desert, the goblins enforce strict neutrality, employing bruisers to beat down anyone foolish enough to start faction brawls within their city walls.",al={"why is gadgetzan neutral","can horde and alliance go to gadgetzan","goblin neutrality gadgetzan"}},{q="What is Zul'Farrak?",a="Zul'Farrak is the fortified desert capital of the Farraki sand trolls. Isolated here since the Great Sundering transformed their ancestral jungle into an arid wasteland, the Sandfury tribe turned hostile to all outsiders, guarding their sacred pools and mysterious shrines from encroaching adventurers.",al={"what is zulfarrak","who lives in zulfarrak","sand troll city"}},{q="What are the insect creatures nesting across the desert?",a="The insectoid beasts are silithid, monstrous colonial burrowers that construct vast hives such as the Gaping Chasm and the Noxious Lair. Their emerging presence in Tanaris has unsettled observers like Senior Surveyor Fizzledowser, recalling the ancient horrors of the War of the Shifting Sands.",al={"what are the bugs in tanaris","tanaris insect hives","silithid in tanaris"}},{q="What is behind the massive stone doors in the south?",a="The monumental gates in the Valley of the Watchers mark the entrance to Uldum, a legendary research facility and holding of the ancient titans. The entrance remains firmly sealed, guarded by colossal stone sentinels and surveyed from afar by curious scholars and goblins.",al={"giant doors in south tanaris","ruins of uldum gates","titan gate tanaris"}},{q="Who dwells inside the Caverns of Time?",a="The Caverns of Time serve as the ancestral lair of the bronze dragonflight and their aspect, Nozdormu. From these hidden, winding depths, the timeless dragons watch over the flow of history, occasionally patrolling the skies high above the southern dunes.",al={"caverns of time lore","what is in caverns of time","dragons in tanaris"}}},ang={["profession:Mining"]="The arid cliffs and rocky outcrops surrounding the dunes offer rich veins of Mithril, Truesilver, Iron, and Gold, along with scattered deposits of Small Thorium in the deeper reaches.",["profession:Herbalism"]="The dry heat nurtures the elusive Firebloom across the shifting dunes, while shaded ruins and damp oases provide shelter for valuable Purple Lotus.",["race:Troll"]="Seeing the Sandfury of Zul'Farrak offers trolls a stark look at their ancient cousins, who mutated and hardened into a brutal culture after being cut off by the Sundering.",["faction:Alliance"]="With no major Alliance strongholds between Dustwallow Marsh and Feralas, the neutral flight master in Gadgetzan serves as a vital staging post for travels across southern Kalimdor.",["faction:Horde"]="Gadgetzan offers Horde scouts a convenient trade hub linking routes from Freewind Post and Camp Mojache directly to the silithid-infested wastes of the far south."},kw={"caverns of time","desert","freebooters","gadgetzan","nozdormu","sandfury","silithid","steamwheedle","tanaris","uldum","zul'farrak"},rel={"subzone:gadgetzan","subzone:zul-farrak","subzone:caverns-of-time","subzone:steamwheedle-port","subzone:ruins-of-uldum","subzone:shimmering-flats","subzone:gaping-chasm","quest:887"},src={"Tanaris (Classic)","Tanaris"}}
